    }
    const kbPrefix = toolType === "suggest_reply"
      ? "suggest"
      : toolType === "knowledge_helper"
      ? "knowledge"
      : "policy";
    const tenant = await resolveTenantScope(conversationId, {
      userId: agent.user_id,
      allowPreActivation: true,
