function modelTokens(text: string): string[] {
  return [
    ...new Set(
      (text.match(/\b[A-Z]{2,}[A-Z0-9]*[- ]?\d{2,}[A-Z0-9-]*\b/g) ?? []).map((
        x,
      ) => x.replace(/\s+/g, "").toUpperCase()),
    ),
  ];
}
function unique(values: Array<string | null | undefined>): string[] {
  return [
    ...new Set(
      values.map((value) => value?.normalize("NFKC").trim()).filter((
        value,
      ): value is string => Boolean(value)),
    ),
  ];
}
function namedTargetTokens(text: string): string[] {
  const targets: string[] = [];
  for (
    const match of text.matchAll(/\b(?:smoke\s+test\s+)?(basic|growth|pro)\b/gi)
  ) {
    const plan = match[1].toLowerCase();
    targets.push(plan);
    if (/smoke\s+test/i.test(match[0])) targets.push(`smoke test ${plan}`);
  }
  for (
    const match of text.matchAll(
      /\b(product|model|sku)\s*[:#-]?\s*([a-z0-9][a-z0-9._/-]{0,80})\b/gi,
    )
  ) {
    targets.push(`${match[1].toLowerCase()} ${match[2].toLowerCase()}`);
    targets.push(match[2].toLowerCase());
  }
  // Canonical commerce objects are semantic targets too. A formatting verb in
  // the same turn (for example, "summarize order TEST-C1") must never cause an
  // earlier product answer to be reused for this newly named object.
  for (
    const match of text.matchAll(
      /\b(order|transaction|invoice|shipment|booking|subscription|account|case|ticket|claim)[ \t]*(?:number|no\.?|id|#|[:\uFF1A-])?[ \t]*((?!(?:is|was|not|has|status|state|confirmed|paid|pending|cancelled|canceled|the|my|a)\b)[a-z0-9][a-z0-9._/-]{1,80})\b/gi,
    )
  ) {
    const kind = match[1].toLowerCase();
    const identifier = match[2].toLowerCase();
    targets.push(`${kind} ${identifier}`);
    targets.push(identifier);
  }
  for (
    const match of text.matchAll(
      /(?:\u8A02\u55AE|\u8BA2\u5355|\u4EA4\u6613|\u767C\u7968|\u53D1\u7968|\u904B\u55AE|\u8FD0\u5355|\u9810\u8A02|\u9884\u8BA2|\u8A02\u95B1|\u8BA2\u9605|\u5E33\u6236|\u8D26\u6237|\u500B\u6848|\u4E2A\u6848|\u5DE5\u55AE|\u5DE5\u5355|\u7D22\u511F|\u7D22\u8D54)[ \t]*(?:\u7DE8\u865F|\u7F16\u53F7|id|#|[:\uFF1A-])?[ \t]*([a-z0-9][a-z0-9._/-]{1,80})/gi,
    )
  ) {
    targets.push(match[0].toLowerCase().replace(/\s+/g, " ").trim());
    targets.push(match[1].toLowerCase());
  }
  return unique([
    ...targets,
    ...modelTokens(text).map((value) => value.toLowerCase()),
  ]);
}
function topicTokens(text: string): string[] {
  const topics: string[] = [];
  const rules: Array<[string, RegExp]> = [
    ["policy", /(?:billing|booking|cancellation|return|warranty)\s+policy|付款政策|預約政策|预约政策|取消政策|退貨政策|退货政策|保養政策|保修政策/i],
    ["warranty", /(?:warranty|保養|保修)/i],
    ["delivery", /(?:delivery|shipping|送貨|送货|物流|派送)/i],
    ["returns", /(?:refund|return|退款|退貨|退货|換貨|换货)/i],
    [
      "price",
      /(?:price|pricing|價錢|价钱|價格|价格|費用|费用|收費|收费|monthly|yearly|每月|每年)/i,
    ],
    [
      "sku_limit",
      /(?:sku|商品|產品|产品).{0,20}(?:limit|上限)|(?:limit|上限).{0,20}(?:sku|商品|產品|产品)/i,
    ],
    [
      "staff_limit",
      /(?:staff|admin(?:[- ]?seat)?|員工|员工|人手).{0,20}(?:limit|上限)|(?:limit|上限).{0,20}(?:staff|admin|員工|员工|人手)/i,
    ],
    [
      "features",
      /(?:feature|included|功能|包括|包含|app|push|crm|會員|会员|ai\s*seo)/i,
    ],
    [
      "specification",
      /(?:\bspec(?:ification)?s?\b|規格|规格|噪音|noise|\bdb\b|dimension|尺寸)/i,
    ],
    ["payment", /(?:payment|付款|支付)/i],
    [
      "order_status",
      /(?:(?:order|transaction|shipment|booking|subscription|case|ticket|claim|訂單|订单|交易|運單|运单|預訂|预订|訂閱|订阅|個案|个案|工單|工单).{0,40}(?:status|state|confirmed|paid|cancelled|canceled|pending|狀態|状态|確認|确认|付款|支付|取消|處理中|处理中)|(?:status|state|狀態|状态).{0,24}(?:order|transaction|shipment|booking|subscription|case|ticket|claim|訂單|订单|交易|運單|运单|預訂|预订|訂閱|订阅|個案|个案|工單|工单))/i,
    ],
  ];
  for (const [topic, pattern] of rules) {
