  const list = (xs: string[]) => xs.map((x, i) => `${i + 1}. ${x}`).join("\n");

  if (latestRequirementsLimitRequest) {
    const lines = currentRequirementLines(state.current_requirements, lang);
    if (!lines.length) return lang === "en" ? en.none : q.none;
