const RAG_VALIDATION_RULES = ["envelope", "citations_shape", "no_match_shape", "no_match_counts", "selected_documents_empty", "document_shape", "optional_authority_shape", "citation_lineage"] as const;
type RagValidationRule = typeof RAG_VALIDATION_RULES[number];
export function ragValidationRule(error: unknown): RagValidationRule | undefined {
  const value = error && typeof error === "object" && "validation_rule" in error ? error.validation_rule : undefined;
  return RAG_VALIDATION_RULES.find(rule => rule === value);
}
const ragAuthorityFailure=(reason:string,validation_rule?:RagValidationRule):never=>{throw Object.assign(new Error("KB_TOOL_FAILURE"),{code:"KB_TOOL_FAILURE",reason,...(validation_rule ? {validation_rule} : {})});};
