      3: ["三", "三", "three"],
      4: ["四", "四", "four"],
      5: ["五", "五", "five"],
      6: ["六", "六", "six"],
      7: ["七", "七", "seven"],
      8: ["八", "八", "eight"],
      9: ["九", "九", "nine"],
      10: ["十", "十", "ten"],
    };
    let v = retainedCorrectionQuantity && typeof e.value === "number" &&
        retainedNumberWords[e.value]
      ? retainedNumberWords[e.value][l]
      : display(e.value);
    if (e.temporal_scope === "historical") v = ["歷史記錄：", "历史记录：", "Historical record: "][l] + v;
