        quotationText,
        orders[String(order)] ? (l === 2 ? "Order: " : "") + orders[String(order)][l] : "",
        payments[String(payment)] ? ["付款：", "付款：", "Payment: "][l] + payments[String(payment)][l] : "",
      ].filter(Boolean).join(l === 2 ? "; " : "，");
      if (transactionText) transactionText += l === 2 ? "." : "。";
  }
  const future=regions.filter(r=>r?.temporal_scope==="future").flatMap(r=>regionNames[String(r?.region)]?.[l]??[]);
  const futureText=future.length ? future.join(l===2?", ":"、")+["只屬未來討論，唔係目前已確認交易。","仅属未来讨论，并非目前已确认交易。"," is a future discussion only, not a confirmed current transaction."][l] : "";
  const sections = [transactionText, ...qualifications, futureText].filter(Boolean);
  const details = sections.length
    ? sections.map(section => section.replace(/[.。]$/, "")).join(l === 2 ? "; " : "；") + (l === 2 ? "." : "。")
    : "";
  return [items, details].filter(Boolean).join(l === 2 ? " " : "").slice(0, 4096);
}

import type { CommerceEntity } from "./commerce-state-contract.ts";
import type { ConversationCommerceState } from "./commerce-state-contract.ts";
import type { CommerceStateEvent } from "./commerce-state-reducer.ts";

export type CustomerJourneyResponseIntent =
  | "advance_decision"
  | "reduce_uncertainty"
  | "answer_known_fact"
  | "request_highest_value_missing_information"
  | "confirm_controlled_update";

export interface CustomerGoalState {
  category: string;
  objective: string;
  journey_stage: string;
  collected: string[];
  missing: string[];
  response_intent: CustomerJourneyResponseIntent;
  source_message_id: string;
  updated_at: string | null;
}

export interface CustomerJourneySignal {
  category: string;
  objective: string;
  journey_stage: string;
  collected: string[];
  missing: string[];
  response_intent: CustomerJourneyResponseIntent;
  reply: string;
  category_source: "explicit" | "active_goal";
}

export interface CustomerJourneyPlan {
  status: "advance" | "ambiguous" | "none";
  reason: string;
  goal: CustomerGoalState | null;
  entity_id: string | null;
  reply: string | null;
  events: CommerceStateEvent[];
}

const GOAL_ATTRIBUTE = "customer_goal";

function clean(value: unknown, max = 240): string {
  return typeof value === "string"
    ? value.normalize("NFKC").replace(/\s+/g, " ").trim().slice(0, max)
    : "";
}

function cleanReply(value: unknown, max = 1200): string {
  return typeof value === "string"
    ? value.replace(/\s+/g, " ").trim().slice(0, max)
    : "";
}

function strings(value: unknown, max = 12): string[] {
  if (!Array.isArray(value)) return [];
  return [...new Set(value.map((item) => clean(item, 80)).filter(Boolean))]
    .slice(0, max);
}

function isResponseIntent(
  value: unknown,
): value is CustomerJourneyResponseIntent {
  return [
    "advance_decision",
    "reduce_uncertainty",
    "answer_known_fact",
    "request_highest_value_missing_information",
    "confirm_controlled_update",
  ].includes(String(value));
}

export function readCustomerGoal(value: unknown): CustomerGoalState | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const row = value as Record<string, unknown>;
  const category = clean(row.category, 80);
  const objective = clean(row.objective, 120);
  const journey_stage = clean(row.journey_stage, 120);
  const source_message_id = clean(row.source_message_id, 100);
  if (
    !category || !objective || !journey_stage || !source_message_id ||
    !isResponseIntent(row.response_intent)
  ) return null;
  return {
    category,
    objective,
    journey_stage,
    collected: strings(row.collected),
    missing: strings(row.missing),
    response_intent: row.response_intent,
    source_message_id,
    updated_at: clean(row.updated_at, 80) || null,
  };
}

export function activeCustomerGoal(
  state: ConversationCommerceState,
  category?: string | null,
): { entity_id: string; goal: CustomerGoalState } | null {
  const active = state.entities.filter((entity) =>
    entity.status !== "cancelled" && entity.status !== "deferred" &&
    (!category || entity.category === category)
  ).flatMap((entity) => {
    const goal = readCustomerGoal(entity.attributes[GOAL_ATTRIBUTE]);
    return goal && goal.category === entity.category
      ? [{ entity_id: entity.entity_id, goal }]
      : [];
  });
  if (active.length !== 1) return null;
  return active[0];
}

/**
 * Bind an industry-neutral journey signal to one compatible active entity.
 * A cancelled/deferred entity is never revived, and multiple compatible
 * entities never receive an implicit update.
 */
export function planCustomerJourney(input: {
  signal: CustomerJourneySignal | null;
  state: ConversationCommerceState;
  source_message_id: string;
  occurred_at?: string | null;
}): CustomerJourneyPlan {
  const signal = input.signal;
  if (!signal) {
    return {
      status: "none",
      reason: "NO_CUSTOMER_JOURNEY_SIGNAL",
      goal: null,
      entity_id: null,
      reply: null,
      events: [],
    };
  }
  const activeCompatible = input.state.entities.filter((entity) =>
    entity.category === signal.category && entity.status !== "cancelled" &&
    entity.status !== "deferred"
  );
  const inactiveCompatible = input.state.entities.filter((entity) =>
    entity.category === signal.category &&
    (entity.status === "cancelled" || entity.status === "deferred")
  );
  if (
    activeCompatible.length > 1 ||
    (!activeCompatible.length && inactiveCompatible.length)
  ) {
    return {
      status: "ambiguous",
      reason: activeCompatible.length > 1
        ? "MULTIPLE_COMPATIBLE_GOALS"
        : "INACTIVE_GOAL_NOT_REACTIVATED",
      goal: null,
      entity_id: null,
      reply: null,
      events: [],
    };
  }
  const existing = activeCompatible[0] ?? null;
  const previousGoal = existing
    ? readCustomerGoal(existing.attributes[GOAL_ATTRIBUTE])
    : null;
  const collected = [
    ...new Set([
      ...(previousGoal?.collected ?? []),
      ...strings(signal.collected),
    ]),
  ].slice(0, 12);
  const missing = strings(signal.missing).filter((item) =>
    !collected.includes(item)
  );
  const goal: CustomerGoalState = {
    category: signal.category,
    objective: signal.objective || previousGoal?.objective || "select_product",
    journey_stage: signal.journey_stage,
    collected,
    missing,
    response_intent: signal.response_intent,
    source_message_id: input.source_message_id,
    updated_at: input.occurred_at ?? null,
  };
  const entity_id = existing?.entity_id ?? `${signal.category}:unscoped`;
  const provenance = {
    source_type: "customer" as const,
    source_message_id: input.source_message_id,
    recorded_at: input.occurred_at ?? null,
  };
  const goalEvent: CommerceStateEvent = existing
    ? {
      type: "SET_ENTITY_ATTRIBUTE",
      entity_id,
      key: GOAL_ATTRIBUTE,
      value: goal,
      provenance,
    }
    : {
      type: "ENSURE_ENTITY",
      entity: {
        entity_id,
        category: signal.category,
        quantity: 1,
        status: "researching",
        attributes: { [GOAL_ATTRIBUTE]: goal, quantity_basis: "system_default" },
        constraints: {},
        provenance,
      },
    };
  return {
    status: "advance",
    reason: `CUSTOMER_JOURNEY_${signal.response_intent.toUpperCase()}`,
    goal,
    entity_id,
    reply: cleanReply(signal.reply) || null,
    events: [
      { type: "SET_CONTEXT", intent: goal.objective, topic: goal.category },
      goalEvent,
    ],
  };
}

export function customerJourneyGoalAttribute(): string {
  return GOAL_ATTRIBUTE;
}

/** Default container counts are not customer-requested machine quantities. */
export function customerRequestedQuantity(entity: CommerceEntity): number | null {
  return entity.attributes.quantity_basis === "system_default" ? null : entity.quantity;
}

import type { CommerceSemanticFrame } from "./commerce-semantic-frame.ts";
import type { ConversationCommerceState } from "./commerce-state-contract.ts";
import type { ContextualCandidate } from "./contextual-customer-update.ts";
import type { CustomerJourneySignal } from "./customer-journey-orchestration.ts";
import type { CommerceTurnEntityHint } from "./commerce-state-reducer.ts";
import { createIndustryRegistry, matchesReferenceLabel, type IndustryProfile } from "./industry-agent-registry.ts";
import { validateIndustrySchemaValues } from "./industry-schema.ts";
import {
  HOME_APPLIANCE_CATEGORIES,
  HOME_APPLIANCE_PROFILE_V1,
  HOME_APPLIANCE_ROOMS,
  homeApplianceCustomerJourneySignal,
  homeApplianceContextualCandidate,
} from "./industry-profiles/home-appliance-v1.ts";

export type IndustryLanguage = "zh-TW" | "zh-CN" | "en";

export const INDUSTRY_AGENT_REGISTRY = createIndustryRegistry([HOME_APPLIANCE_PROFILE_V1]);

export function resolveIndustryContextualCandidate(input: {
  text: string;
  history: readonly string[];
  state: ConversationCommerceState;
  language: IndustryLanguage;
}): ContextualCandidate | null {
  const profile = resolveIndustryRuntime({
    texts: [input.text, ...input.history],
    industry_identifier: input.state.current_industry,
  }).profile;
  if (profile && profile.id !== HOME_APPLIANCE_PROFILE_V1.id) return null;
  const candidate = homeApplianceContextualCandidate(input);
  // A room-only phrase without a selected profile can request clarification,
  // but cannot authoritatively bind to an unknown product or service domain.
  return !profile && candidate?.action === "scoped_update"
    ? { ...candidate, context_sufficient: false }
    : candidate;
}

/** A historical industry is not a licence to mutate that industry's state on
 * a later topic. Use the validated current-turn frame before restoring any
 * implicit industry journey. Current-turn explicit product references remain
 * authoritative; absent or low-confidence frames retain the existing safe
 * scoped-observation contract in the industry profile. */
export function resolveIndustryCustomerJourney(input: {
  text: string;
  state: ConversationCommerceState;
  language: IndustryLanguage;
  semantic_frame?: CommerceSemanticFrame | null;
}): CustomerJourneySignal | null {
  const current = input.semantic_frame;
  if (current && current.confidence >= 0.72 &&
      current.ambiguity.is_ambiguous === false &&
      typeof current.topic === "string" && current.topic.trim()) {
    const newTopic = clean(current.topic).toLowerCase();
    const historical = clean(input.state.current_topic).toLowerCase();
    const explicitAppliance = HOME_APPLIANCE_CATEGORIES.some(category =>
      category.aliases.some(alias => matchesReferenceLabel(input.text, alias)));
    const semanticAppliance = HOME_APPLIANCE_CATEGORIES.some(category =>
      category.key === newTopic || category.aliases.some(alias =>
        matchesReferenceLabel(newTopic, alias)));
    if (historical && newTopic !== historical && !semanticAppliance &&
        !explicitAppliance) return null;
  }
  const profile = resolveIndustryRuntime({
    texts: [input.text],
    industry_identifier: input.state.current_industry,
  }).profile;
  if (profile && profile.id !== HOME_APPLIANCE_PROFILE_V1.id) return null;
  return homeApplianceCustomerJourneySignal(input);
}

export interface IndustryRuntimeResolution {
  industry_id: string | null;
  profile: IndustryProfile | null;
  hints: CommerceTurnEntityHint[];
}

function clean(value: unknown): string {
  return typeof value === "string" ? value.normalize("NFKC").replace(/\s+/g, " ").trim() : "";
}

function matches(text: string, aliases: readonly string[]): boolean {
  const lower = clean(text).toLowerCase();
  return aliases.some(
    (alias) => matchesReferenceLabel(lower,alias),
  );
}

export function resolveIndustryProfile(
  identifier: string | null | undefined,
): IndustryProfile | null {
  return INDUSTRY_AGENT_REGISTRY.resolve(identifier);
}

export function resolveIndustryRuntime(input: {
  texts: readonly string[];
  semantic_frame?: CommerceSemanticFrame | null;
  industry_identifier?: string | null;
}): IndustryRuntimeResolution {
  const explicit = INDUSTRY_AGENT_REGISTRY.resolve(input.industry_identifier);
  const detected = input.texts.some((text) =>
    HOME_APPLIANCE_CATEGORIES.some((category) => matches(text, category.aliases)),
  )
    ? HOME_APPLIANCE_PROFILE_V1
    : null;
  const hasExplicitIdentifier = Boolean(clean(input.industry_identifier));
  const profile = hasExplicitIdentifier ? explicit : detected;
  if (!profile) return { industry_id: null, profile: null, hints: [] };

  const hints = new Map<string, CommerceTurnEntityHint>();
  for (const text of input.texts) {
    const categories = HOME_APPLIANCE_CATEGORIES.filter((category) =>
      matches(text, category.aliases),
    );
    const rooms = HOME_APPLIANCE_ROOMS.filter((room) => matches(text, room.aliases));
    for (const category of categories) {
      for (const room of rooms.length ? rooms : [null]) {
        const entityId = `${category.key}:${room?.key ?? "unscoped"}`;
        hints.set(entityId, {
          entity_id: entityId,
          category: category.key,
          aliases: [...category.aliases, ...(room?.aliases ?? [])],
          attributes: {
            industry_profile_id: profile.id,
            industry_profile_version: profile.version,
          },
        });
      }
    }
  }

  // Validate only explicitly supplied semantic fields. Missing optional facts stay
  // absent so the industry layer can never invent product or policy state.
  for (const entity of input.semantic_frame?.entities ?? []) {
    const values: Record<string, unknown> = {};
    const candidate = {
      product: entity.name,
      model: entity.model,
      ...entity.attributes,
      ...entity.constraints,
    };
    for (const field of profile.schema.fields) {
      const value = candidate[field.key as keyof typeof candidate];
      if (value !== undefined && value !== null) values[field.key] = value;
    }
    if (!validateIndustrySchemaValues(profile.schema, values).valid) continue;
    const semanticHint = [...hints.values()].find((hint) =>
      (hint.aliases ?? []).some((alias) =>
        matchesReferenceLabel(clean(entity.name),clean(alias)),
      ),
    );
    if (semanticHint)
      semanticHint.attributes = { ...semanticHint.attributes, industry_fields: values };
  }
  return { industry_id: profile.id, profile, hints: [...hints.values()] };
}

export function industryEntityLabel(entityId: string, language: IndustryLanguage): string | null {
  const [categoryKey, roomKey] = entityId.split(":");
  const category = HOME_APPLIANCE_CATEGORIES.find((item) => item.key === categoryKey ||
    item.aliases.some(alias => clean(alias).toLowerCase() === clean(categoryKey).toLowerCase()));
  if (!category) return null;
  const room = HOME_APPLIANCE_ROOMS.find((item) => item.key === roomKey);
  if (!room) return category.label[language];
  return language === "en"
    ? `${room.label.en} ${category.label.en}`
    : `${room.label[language]}${category.label[language]}`;
}

/** Fallback realization only: a canonical explicit unit remains the caller's authority. */
export function industryEntityQuantityUnit(
  entityId: string, language: IndustryLanguage, quantity: number,
): string | null {
  const categoryKey = entityId.split(":")[0];
  if (!HOME_APPLIANCE_CATEGORIES.some((category) => category.key === categoryKey ||
    category.aliases.some(alias => clean(alias).toLowerCase() === clean(categoryKey).toLowerCase()))) return null;
  return language === "en" ? (quantity === 1 ? "unit" : "units") : "部";
}

import { validateIndustrySchema, type IndustrySchema } from "./industry-schema.ts";

export interface IndustryProfile {
  id: string;
  version: string;
  aliases: readonly string[];
  schema: IndustrySchema;
  category_bindings?: readonly { key: string; aliases: readonly string[] }[];
}

export interface IndustryRegistry {
  resolve(identifier: string | null | undefined): IndustryProfile | null;
  profiles(): readonly IndustryProfile[];
}

function normalize(value: string): string {
  return value
    .normalize("NFKC")
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
}

export function createIndustryRegistry(profiles: readonly IndustryProfile[]): IndustryRegistry {
  const entries = new Map<string, IndustryProfile>();
  for (const profile of profiles) {
    if (!/^[a-z][a-z0-9_]{1,63}$/.test(profile.id))
      throw new Error(`invalid_industry_id:${profile.id}`);
    if (!/^\d+\.\d+\.\d+$/.test(profile.version))
      throw new Error(`invalid_profile_version:${profile.id}`);
    const validation = validateIndustrySchema(profile.schema);
    if (!validation.valid)
      throw new Error(`invalid_industry_schema:${profile.id}:${validation.errors.join(",")}`);
    if (profile.schema.id !== profile.id)
      throw new Error(`industry_schema_binding_mismatch:${profile.id}`);
    for (const candidate of [profile.id, ...profile.aliases]) {
      const key = normalize(candidate);
      if (!key || entries.has(key)) throw new Error(`duplicate_industry_identifier:${key}`);
      entries.set(key, profile);
    }
  }
  const frozen = Object.freeze([...profiles]);
  return Object.freeze({
    resolve(identifier: string | null | undefined) {
      return identifier ? (entries.get(normalize(identifier)) ?? null) : null;
    },
    profiles() {
      return frozen;
    },
  });
}

/** Match an authoritative label, not a substring inside another identifier.
 * ASCII labels use token boundaries; CJK labels retain normal unspaced usage.
 * No taxonomy, inference, tenant lookup or state mutation occurs here.
 */
export function matchesReferenceLabel(text: string, label: string): boolean {
  const value=text.normalize("NFKC").toLowerCase();
  const key=label.normalize("NFKC").trim().toLowerCase();
  if(key.length<2) return false;
  let from=0;
  while(from<=value.length-key.length){
    const at=value.indexOf(key,from);if(at<0)return false;
    const ascii=(c:string)=>/[a-z0-9_-]/i.test(c);
    const left=!ascii(key[0]) || at===0 || !ascii(value[at-1]);
    const end=at+key.length;
    const right=!ascii(key[key.length-1]) || end===value.length || !ascii(value[end]);
    if(left&&right)return true;
    from=at+1;
  }
  return false;
}

export type IndustryFieldType = "string" | "number" | "boolean" | "object";

export interface IndustrySchemaField {
  key: string;
  type: IndustryFieldType;
  required: boolean;
  description: string;
}

export interface IndustrySchema {
  id: string;
  version: string;
  fields: readonly IndustrySchemaField[];
}

export interface IndustrySchemaValidation {
  valid: boolean;
  errors: string[];
}

const IDENTIFIER = /^[a-z][a-z0-9_]{1,63}$/;
const VERSION = /^\d+\.\d+\.\d+$/;
const FIELD_TYPES = new Set<IndustryFieldType>(["string", "number", "boolean", "object"]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

export function validateIndustrySchema(schema: IndustrySchema): IndustrySchemaValidation {
  const errors: string[] = [];
  if (!IDENTIFIER.test(schema.id)) errors.push("invalid_schema_id");
  if (!VERSION.test(schema.version)) errors.push("invalid_schema_version");
  if (!Array.isArray(schema.fields) || schema.fields.length === 0)
    errors.push("empty_schema_fields");
  const seen = new Set<string>();
  for (const field of schema.fields ?? []) {
    if (!IDENTIFIER.test(field.key)) errors.push(`invalid_field_key:${field.key}`);
    if (seen.has(field.key)) errors.push(`duplicate_field_key:${field.key}`);
    seen.add(field.key);
    if (!FIELD_TYPES.has(field.type)) errors.push(`invalid_field_type:${field.key}`);
    if (typeof field.required !== "boolean") errors.push(`invalid_field_required:${field.key}`);
    if (!field.description.trim()) errors.push(`missing_field_description:${field.key}`);
  }
  return { valid: errors.length === 0, errors };
}

export function validateIndustrySchemaValues(
  schema: IndustrySchema,
  value: unknown,
): IndustrySchemaValidation {
  const definition = validateIndustrySchema(schema);
  if (!definition.valid) return definition;
  if (!isRecord(value)) return { valid: false, errors: ["industry_values_not_object"] };
  const errors: string[] = [];
  const fields = new Map(schema.fields.map((field) => [field.key, field]));
  for (const key of Object.keys(value)) if (!fields.has(key)) errors.push(`unknown_field:${key}`);
  for (const field of schema.fields) {
    const fieldValue = value[field.key];
    if (fieldValue === undefined || fieldValue === null) {
      if (field.required) errors.push(`missing_required_field:${field.key}`);
      continue;
    }
    const matches =
      field.type === "object" ? isRecord(fieldValue) : typeof fieldValue === field.type;
    if (!matches || (field.type === "number" && !Number.isFinite(fieldValue))) {
      errors.push(`invalid_field_value:${field.key}`);
    }
  }
  return { valid: errors.length === 0, errors };
}

