function journeyObservations(text: string): string[] {
  const values: string[] = [];
  if (hasTwoBedroomLivingContext(text)) values.push("space_plan");
  if (/(?:細房|小房|大房|書房|书房|客廳|客厅|living room|bedroom|study).{0,14}\d{2,4}\s*(?:平方呎|平方英尺|sq\.?\s*ft|ft²|呎)|\d{2,4}\s*(?:平方呎|平方英尺|sq\.?\s*ft|ft²|呎).{0,14}(?:房|客廳|客厅|living room|bedroom|study)/iu.test(text)) values.push("room_sizes");
  if (/(?:窗口位|窗口機|窗口机|分體位|分体位|分體機|分体机|window\s*(?:opening|unit|air)|split[- ]?unit|installation\s*type)/iu.test(text)) values.push("installation_type");
  if (customerSunExposure(text) !== null) values.push("sunlight");
  if (/(?:闊|宽|高|深|width|height|depth).{0,12}\d{2,4}\s*(?:mm|毫米)/iu.test(text)) values.push("dimensions");
  // "升級" / "升级" is a decision about upgrades, not an appliance
  // capacity observation. Only an explicit capacity word or a bounded
  // measurement qualifies; the prior active goal is not enough on its own.
  if (/(?:容量|公升|(?:\d+(?:\.\d+)?\s*(?:升|l\b|litres?|liters?))|(?:幾多|几多|多少)\s*升|幾多人|几个人|people)/iu.test(text)) values.push("capacity");
  return [...new Set(values)];
}

function journeyObjective(text: string, previous: string | null): string {
  if (/(?:換|更換|替換|replace|replacement)/iu.test(text)) return "replace_existing_appliance";
  if (/(?:比較|对比|compare)/iu.test(text)) return "compare_products";
  return previous || "select_product";
}

function isJourneyStart(text: string): boolean {
  return /(?:點揀|点选|點選|點樣揀|怎样选|怎樣選|如何選|如何选|買咩|买什么|推薦|推荐|應該點|应该怎么|how\s+(?:should\s+i|do\s+i|to)\s+(?:choose|select)|help\s+(?:me\s+)?choose|想.{0,12}(?:換|买|買|揀|选|選|睇|看)|replace)/iu.test(text);
}

export function homeApplianceCustomerJourneySignal(input: {
  text: string;
  state: ConversationCommerceState;
  language: "zh-TW" | "zh-CN" | "en";
}): CustomerJourneySignal | null {
  const text = input.text.normalize("NFKC").trim();
  if (!text || /(?:取消|唔要|不要|暫時唔|暂时不|defer|hold off|cancel)/iu.test(text)) return null;
  if (hasOneEachBedroomAllocation(text) || hasOneLivingRoomAllocation(text)) return null;
  const explicit = HOME_APPLIANCE_CATEGORIES.filter((category) =>
    category.aliases.some((alias) => matchesReferenceLabel(text,alias))
  );
  if (explicit.length > 1) return null;
  const prior = activeCustomerGoal(input.state);
  const category = explicit[0]?.key ?? prior?.goal.category ??
    (HOME_APPLIANCE_CATEGORIES.some((item) => item.key === input.state.current_topic) ? input.state.current_topic : null);
  if (!category) return null;
  const policy = HOME_APPLIANCE_JOURNEY_POLICIES[category];
  if (!policy) return null;
  const observed = journeyObservations(text);
  const windowPair=category==="air_conditioner"?customerDimensionPair(text):null;
  const current=prior?input.state.entities.find(e=>e.entity_id===prior.entity_id):null;
  const windowContext=current?.attributes.installation_type==="window_unit" || input.state.installation.pending_checks.includes("window_opening_check");
  if(windowPair&&windowContext)observed.push("window_dimensions");
  const windowScope=HOME_APPLIANCE_ROOMS.find(r=>r.aliases.some(alias=>matchesReferenceLabel(text,alias)))?.key;
  const pending=current?.attributes.window_opening_observation as Record<string,unknown>|undefined;
  if(pending?.scope===null && windowScope)observed.push("window_scope");
  // A previously active appliance is *not* authority to classify an unrelated
  // new topic as that appliance. Implicit continuations require a fresh,
  // category-compatible observation (room/site/sunlight or legitimate capacity)
  // rather than a generic "compare / upgrade / want" expression. Explicit
  // category mentions continue to work exactly as before.
  if (!explicit.length && !observed.some(value =>
    policy.required.includes(value) ||
    category === "air_conditioner" && ["space_plan", "window_dimensions", "window_scope"].includes(value)
  )) return null;
  const fridge = input.state.entities.filter((entity) => entity.category === "refrigerator" && !["cancelled", "deferred"].includes(entity.status));
  const dimensionValues: Record<string, number> = {};
  if (category === "refrigerator") {
    for (const [key, words] of [["width", "闊|寬|宽|width"], ["height", "高|height"], ["depth", "深|depth"]]) {
      const priorValue = fridge.length === 1 ? fridge[0].constraints[`max_${key}_mm`] : undefined;
      const raw = text.match(new RegExp(`(?:${words}).{0,12}?(\\d{2,4})\\s*(?:mm|毫米)`, "iu"))?.[1] ??
        text.match(new RegExp(`(\\d{2,4})\\s*(?:mm|毫米)\\s*(?:${words})`, "iu"))?.[1];
      const value = raw ? Number(raw) : Number(priorValue);
      if (Number.isFinite(value) && value > 0) dimensionValues[key] = value;
    }
    const index = observed.indexOf("dimensions");
    if (index >= 0) observed.splice(index, 1);
    if (Object.keys(dimensionValues).length === 3) observed.push("dimensions");
  }
  if (!isJourneyStart(text) && !observed.length) return null;
  const collected = [...new Set([...(prior?.goal.category === category ? prior.goal.collected : []), ...observed])];
  const operationalMissing = policy.required.filter((item) => !collected.includes(item));
  const missing = [...operationalMissing, ...policy.decision_outputs];
  const next = operationalMissing[0] ?? null;
  return {
    category,
    objective: journeyObjective(text, prior?.goal.category === category ? prior.goal.objective : null),
    journey_stage: policy.stage,
    collected,
    missing,
    response_intent: next ? "request_highest_value_missing_information" : "advance_decision",
    reply: pending?.scope===null && windowScope ? (input.language==="en"?`The ${pending.width_mm} mm × ${pending.height_mm} mm opening belongs to ${windowScope.replaceAll("_"," ")}; the other rooms remain separate.`:input.language==="zh-CN"?`已记下这组 ${pending.width_mm} mm × ${pending.height_mm} mm 尺寸属于${HOME_APPLIANCE_ROOMS.find(r=>r.key===windowScope)?.label["zh-CN"]??windowScope}；其他房间仍分开记录。`:`已記低呢組 ${pending.width_mm} mm × ${pending.height_mm} mm 尺寸屬於${HOME_APPLIANCE_ROOMS.find(r=>r.key===windowScope)?.label["zh-TW"]??windowScope}；其他房間仍分開記錄。`)
      : windowPair&&windowContext ? (input.language==="en"?`I have a width of ${windowPair.width_mm} mm and height of ${windowPair.height_mm} mm. ${windowScope?"Those measurements belong to the named room; product fit still needs verified specifications.":"Which room does this opening belong to? I have not applied these dimensions to the other rooms."}`:input.language==="zh-CN"?`已记下宽 ${windowPair.width_mm} mm、高 ${windowPair.height_mm} mm。${windowScope?"这是所指房间的窗口尺寸；产品是否适合仍需核实规格。":"这是哪个房间的窗口？我没有把这一组尺寸套用到其他房间。"}`:`已記低闊 ${windowPair.width_mm} mm、高 ${windowPair.height_mm} mm。${windowScope?"呢組係所指房間嘅窗口尺寸；產品是否合適仍要核實規格。":"呢個係邊間房嘅窗口？我未將呢組尺寸套用到其他房間。"}`)
      : category === "air_conditioner" && customerSunExposure(text)==="none" && !next ? (input.language==="en"?"I have noted the reported absence of west-facing afternoon sun. What are the usable width and height of each window opening? Suitability still requires verified product data and a site check.":input.language==="zh-CN"?"已记下没有西晒；仍需按各房面积及安装条件核对。各窗口可用的宽度和高度是多少？型号适用性仍须核实。":"已記低冇西斜；仍需按各房面積及安裝條件核對。各窗口可用嘅闊度同高度係幾多？型號適用性仍須核實。")
      : category === "refrigerator" && next === "dimensions" && Object.keys(dimensionValues).length
      ? (() => {
        const names: Record<string, [string,string,string]> = {width:["闊度","宽度","width"],height:["高度","高度","height"],depth:["深度","深度","depth"]};
        const l = input.language === "en" ? 2 : input.language === "zh-CN" ? 1 : 0;
        const provided = Object.entries(dimensionValues).map(([key,value]) => `${names[key][l]} ${value} mm`).join(", ");
        const missing = ["width","height","depth"].filter((key) => !(key in dimensionValues)).map((key) => names[key][l]).join(l === 2 ? " and " : "同");
        return l === 2 ? `I have ${provided}. What are the limits for ${missing}?` : l === 1
          ? `已知${provided}。${missing}的上限分别是多少？` : `已知${provided}。${missing}上限各係幾高／幾深？`;
      })()
      : next ? policy.prompts[input.language][next] : policy.ready[input.language],
    category_source: explicit.length === 1 ? "explicit" : "active_goal",
  };
}

/** Optional profile vocabulary for the universal contextual update contract. */
export function homeApplianceContextualCandidate(input: {
  text: string;
  history: readonly string[];
  state: ConversationCommerceState;
  language: "zh-TW" | "zh-CN" | "en";
}): ContextualCandidate | null {
  const text = input.text.normalize("NFKC").trim();
  const customerHistory = input.history.join(" ");
  const explicit = HOME_APPLIANCE_CATEGORIES.filter((category) =>
    category.aliases.some((alias) => matchesReferenceLabel(text,alias))
  );
  if (explicit.length > 1) return null;
  const topic = explicit[0]?.key ?? input.state.current_topic;
  const roomContext = hasTwoBedroomLivingContext(customerHistory);
  const currentRoomContext = hasTwoBedroomLivingContext(text);
  const language = input.language;
  const sizingQuestion = /(?:想問|想问|請教|请教|想了解|想換|想换|點揀|点揀|如何選|如何选|應該點揀|应该怎么选|how|help|replace).{0,40}(?:匹數|匹数|冷氣|冷气|空調|空调|air\s*condition)|(?:冷氣|冷气|空調|空调|air\s*condition).{0,40}(?:點揀|点揀|如何選|如何选|應該|应该|choose|select|sizing|capacity)/iu.test(text)
    && !/(?:一\s*部|兩\s*部|两\s*部|\d+\s*部)/i.test(text);
  if (topic === "air_conditioner" && explicit.length === 1 && sizingQuestion && currentRoomContext &&
    !journeyObservations(text).some((fact) => fact !== "space_plan")) {
    return {
      topic, topic_source: "explicit", action: "enquiry", values: [],
      context_sufficient: true,
      reply: language === "en"
        ? "I can help size each AC for the bedrooms and living room. What is each room's area, afternoon sun exposure, and window or installation arrangement?"
        : language === "zh-CN"
        ? "两间房和客厅要分别估冷气匹数。请给我各自面积、下午日晒情况，以及窗口和安装方式。"
        : "我會按兩間房同客廳逐個空間幫你揀冷氣。下一步需要細房、大房同客廳各自嘅平方呎面積。",
      clarification: "",
    };
  }
  const bedroomAllocation = hasOneEachBedroomAllocation(text);
  const livingAllocation = hasOneLivingRoomAllocation(text);
  if (!bedroomAllocation && !livingAllocation) return null;
  if (/[?？]/.test(text)) return null;
  const clarification = language === "en"
    ? "Which product is this for, and how many bedrooms and living rooms do you mean?"
    : language === "zh-CN"
    ? "这是哪种产品？请确认有几间房和几个客厅需要各一部。"
    : "你講緊邊種產品？請確認有幾間房同幾個客廳要各一部。";
  const safeRooms = currentRoomContext || roomContext;
  const typo = /廤/.test(text);
  const complete = topic === "air_conditioner" && bedroomAllocation && livingAllocation && safeRooms &&
    (!typo || (roomContext && input.state.current_topic === "air_conditioner"));
  const values = complete
    ? ([
      { scope: "living_room", attribute: "quantity", action: "set", value: 1 },
      { scope: "bedroom_1", attribute: "quantity", action: "set", value: 1 },
      { scope: "bedroom_2", attribute: "quantity", action: "set", value: 1 },
    ] as const).map((v) => ({ ...v }))
    : [];
  return {
    topic: explicit[0]?.key ?? "air_conditioner",
    topic_source: explicit.length === 1 ? "explicit" : "profile",
    action: "scoped_update",
    values,
    aggregate_quantity: complete ? 3 : undefined,
    context_sufficient: complete,
    clarification,
    reply: language === "en"
      ? "I have one unit for the living room and one for each of the two bedrooms: three units in total. This is a requirement, not an order."
      : language === "zh-CN"
      ? "记下客厅一部、两间房各一部，共三部；这只是选购要求，并非已落单。"
      : "記低客廳一部、兩間房各一部，共三部；呢個係選購要求，未落單。",
  };
}

