      Number.isInteger(config.maxOutputTokens) && config.maxOutputTokens>0 && config.maxOutputTokens<=4096 && config.temperature===0 &&
      only(config.thinkingConfig,["thinkingBudget"]) && config.thinkingConfig.thinkingBudget===0 &&
