  source_created_at: string;
  latest: string;
  /** Raw server-loaded customer content when latest is a bounded business
   * projection or an Agent Assist query. The staff query is not customer fact. */
  source_content?: string;
  /** Shared caller deadline for all context reads, never reset per query. */
  signal?: AbortSignal;
  recent_history: SemanticRecoveryHistoryRow[];
  /** Either the existing persisted Memory row or its canonical memory value. */
  memory?: unknown;
  /** For example, Commerce.source_message_id. Missing IDs are not trusted. */
  requested_source_message_ids?: string[];
  /** Locating terms only, never a model-supplied tenant, filter or SQL fragment. */
  search_terms?: string[];
}

export interface SemanticHistoryRecoveryResult {
  rows: RecoveredCustomerHistoryRow[];
  source_verified: boolean;
  memory_source_verified: boolean;
  usable_source_message_ids: string[];
  candidate_source_message_ids: string[];
  context_incomplete: boolean;
  reason: string;
  read_count: number;
  scanned_rows: number;
}

const CUSTOMER = new Set(["visitor", "customer", "user"]);
const clean = (value: unknown): string => typeof value === "string"
  ? value.normalize("NFKC").replace(/\s+/gu, " ").trim() : "";
const normalized = (value: unknown): string => clean(value).toLocaleLowerCase();
const record = (value: unknown): Record<string, any> | null =>
  value !== null && typeof value === "object" && !Array.isArray(value) ? value as Record<string, any> : null;
const distinct = (values: string[]): string[] => [...new Set(values.filter(Boolean))];

function time(value: unknown): number | null {
  if (typeof value !== "string" || !value.trim()) return null;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function compareTime(a: string, b: string): number {
  const millis = time(a)! - time(b)!;
  if (millis) return millis;
  // PostgreSQL timestamps can retain microseconds that Date.parse truncates.
  const remainder = (value: string) => Number((value.match(/\.(\d+)(?:Z|[+-]\d{2}:?\d{2})$/iu)?.[1] ?? "")
    .padEnd(9, "0").slice(3, 9));
  return remainder(a) - remainder(b);
}

/** Timestamp precision and UUID tie-breaking shared by callers that assemble
 * the semantic window. Invalid source boundaries must never sort as equal. */
export function compareMessageChronology(
  a: {id: string; created_at: string},
  b: {id: string; created_at: string},
): number {
  if (!a.id || !b.id || time(a.created_at) === null || time(b.created_at) === null) {
    throw new Error("invalid_message_chronology");
  }
  return compareTime(a.created_at, b.created_at) || a.id.localeCompare(b.id);
}

/** Stable cutoff: no future turn, including a later ID with the same timestamp. */
export function isCustomerHistoryAtOrBefore(
  row: SemanticRecoveryHistoryRow,
  boundary: { source_message_id: string; source_created_at: string },
): boolean {
  const created = time(row.created_at), cutoff = time(boundary.source_created_at);
  return Boolean(row.id && CUSTOMER.has(String(row.role ?? "").toLowerCase()) &&
    created !== null && cutoff !== null &&
    (compareTime(row.created_at!, boundary.source_created_at) < 0 ||
      compareTime(row.created_at!, boundary.source_created_at) === 0 && row.id <= boundary.source_message_id));
}

function validAnchor(value: unknown): value is FactualReadAnchor {
  const anchor = record(value);
  return Boolean(anchor && clean(anchor.source_message_id) && anchor.source_message_id.length <= 80 && time(anchor.created_at) !== null &&
    typeof anchor.customer_text === "string" && anchor.customer_text.length <= 600 &&
    Array.isArray(anchor.subjects) && anchor.subjects.length <= 8 &&
    anchor.subjects.every((v: unknown) => typeof v === "string" && v.length >= 2 && v.length <= 160) &&
    Array.isArray(anchor.subject_source_message_ids) && anchor.subject_source_message_ids.length <= 16 &&
    anchor.subject_source_message_ids.every((v: unknown) => typeof v === "string" && v.length > 0 && v.length <= 80) &&
    Array.isArray(anchor.requested_facts) && anchor.requested_facts.length <= 16 &&
    anchor.requested_facts.every((v: unknown) => typeof v === "string" && v.length > 0 && v.length <= 160) &&
    (anchor.text_truncated === undefined || typeof anchor.text_truncated === "boolean"));
}

export function factualReadAnchors(value: unknown): FactualReadAnchor[] {
  return Array.isArray(value) ? value.filter(validAnchor).slice(-SEMANTIC_HISTORY_RECOVERY_LIMITS.anchor_count) : [];
}

/** A proposed label must occur in an actual customer source. Semantic labels
 * are useful locators but cannot mint a name absent from the conversation. */
export function buildFactualReadAnchor(input: {
  source_message_id: string;
  source_created_at: string;
  rows: SemanticRecoveryHistoryRow[];
  request?: FactualReadRequest;
  previous?: FactualReadAnchor[];
}): FactualReadAnchor | null {
  const source = input.rows.find(row => row.id === input.source_message_id &&
    CUSTOMER.has(String(row.role ?? "").toLowerCase()));
  if (!source || !clean(source.content) || time(input.source_created_at) === null ||
    source.created_at && (time(source.created_at) === null || compareTime(source.created_at, input.source_created_at) !== 0) ||
    input.request && input.request.source_message_id !== input.source_message_id) return null;
  const sourceText = clean(source.content);
  const cited = new Set(input.request?.subject_source_message_ids ?? []);
  const locatingRows = input.rows.filter(row => row.id && CUSTOMER.has(String(row.role ?? "").toLowerCase()) &&
    (row.id === input.source_message_id || cited.has(row.id)) &&
    (!row.created_at || isCustomerHistoryAtOrBefore(row, input)));
  const previous = factualReadAnchors(input.previous).filter(anchor => cited.has(anchor.source_message_id) &&
    isCustomerHistoryAtOrBefore({id: anchor.source_message_id, role: "visitor", created_at: anchor.created_at}, input));
  const proofs = [...locatingRows.map(row => ({id: row.id!, text: clean(row.content)})),
    ...previous.map(anchor => ({id: anchor.source_message_id, text: anchor.customer_text}))];
  const subjects: string[] = [], subjectIds: string[] = [];
  for (const label of distinct((input.request?.subjects ?? []).map(clean)).slice(0, 8)) {
    if (label.length < 2 || label.length > 160) continue;
    const bound = proofs.filter(proof => normalized(proof.text).includes(normalized(label)));
    if (!bound.length) continue;
    subjects.push(label);
    subjectIds.push(...bound.map(proof => proof.id));
  }
  return {
    source_message_id: input.source_message_id,
    created_at: source.created_at || input.source_created_at,
    customer_text: sourceText.slice(0, 600),
    subjects,
    subject_source_message_ids: distinct(subjectIds).slice(0, 16),
    requested_facts: distinct((input.request?.requested_facts ?? []).map(clean)).filter(value => value.length <= 160).slice(0, 16),
    ...(sourceText.length > 600 ? {text_truncated: true} : {}),
  };
}

/** These cues only trigger a bounded read; they never resolve a subject or
 * authorize a fact. An unfamiliar short question gets the same recovery as a
 * known facet, rather than a price/stock-only shortcut. */
function mayNeedHistoricalContext(latest: string): boolean {
  return latest.length <= 160 ||
    /(?:之前|先前|剛才|刚才|頭先|頭嗰|头嗰|最初|原先|上次|嗰|呢|該|该|其餘|其余|前者|後者|后者|另外一)|\b(?:it|its|this|that|these|those|earlier|previous|former|latter|first|second|original|again|both|other|back|above)\b/iu.test(latest);
}

function locatingTerms(latest: string, supplied: string[], anchors: FactualReadAnchor[]): string[] {
  const stop = /^(?:what|when|where|which|does|could|would|should|about|please|price|stock|delivery|policy|tell|have|that|this|these|those|previous|earlier|first|second|other|with|from|still|same|again)$/iu;
  const literalAnchors = anchors.flatMap(anchor => anchor.subjects)
    .filter(subject => normalized(latest).includes(normalized(subject)));
  const tokens = latest.match(/[\p{L}\p{N}]+(?:[-_/][\p{L}\p{N}]+)+|[A-Za-z][A-Za-z0-9]{3,}/gu) ?? [];
  return distinct([...supplied, ...literalAnchors, ...tokens].map(clean))
    .filter(value => value.length >= 2 && value.length <= 80 && !stop.test(value))
    .slice(0, SEMANTIC_HISTORY_RECOVERY_LIMITS.search_queries);
}

/** CJK text has no reliable whitespace word boundaries. Bounded character
 * fragments retrieve possible original wording without a product/intent
 * vocabulary. They are only recall hints; the semantic pass sees the full
 * source sentences and must still resolve ambiguity. */
function cjkLocatingFragments(latest: string): string[] {
  const fragments: string[] = [];
  for (const run of latest.match(/[\p{Script=Han}]{2,}/gu) ?? []) {
    const width = Math.min(4, run.length);
    for (let i = 0; i <= run.length - width; i++) fragments.push(run.slice(i, i + width));
  }
  const all = distinct(fragments);
  return all.length <= 16 ? all : Array.from({length: 16}, (_, i) => all[Math.floor(i * (all.length - 1) / 15)]);
}

/** Only these validated values enter a PostgREST OR expression. A supplied
 * message/tenant/name can never become an arbitrary filter expression. */
function olderThanFilter(row: RecoveredCustomerHistoryRow): string | null {
  if (!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/iu.test(row.id) || time(row.created_at) === null) return null;
  const fraction = row.created_at.match(/\.(\d+)(?:Z|[+-]\d{2}:?\d{2})$/iu)?.[1] ?? "000";
  const date = new Date(row.created_at).toISOString().replace(/\.\d{3}Z$/u, `.${fraction}Z`);
  return `created_at.lt.${date},and(created_at.eq.${date},id.lt.${row.id})`;
}

/** Read-only, on-demand recovery using the existing conversation/messages
 * store. No model call, polling, schema, second memory or merchant fact source.
 * Results are candidates for semantic understanding, never a chosen referent. */
export async function recoverSemanticHistory(
  client: SemanticHistoryRecoveryClient,
  input: SemanticHistoryRecoveryInput,
): Promise<SemanticHistoryRecoveryResult> {
  const result: SemanticHistoryRecoveryResult = {
    rows: [], source_verified: false, memory_source_verified: false,
    usable_source_message_ids: [], candidate_source_message_ids: [],
    context_incomplete: false, reason: "recent_context", read_count: 0, scanned_rows: 0,
  };
  const fail = (reason: string) => ({...result, context_incomplete: true, reason});
  if (!clean(input.company_id) || !clean(input.conversation_id) || !clean(input.source_message_id) ||
    time(input.source_created_at) === null || !clean(input.latest) ||
    !clean(input.source_content ?? input.latest)) return fail("invalid_source_boundary");
  const selected = "id,conversation_id,role,content,created_at,is_recalled";
  const byId = new Map<string, RecoveredCustomerHistoryRow>();
  const validRow = (value: unknown): value is RecoveredCustomerHistoryRow => {
    const row = record(value);
    return Boolean(row && row.conversation_id === input.conversation_id && row.is_recalled === false &&
      typeof row.content === "string" && clean(row.content) && isCustomerHistoryAtOrBefore(row, input));
  };
  const withSignal = (query: any) => input.signal ? query.abortSignal(input.signal) : query;
  const base = () => withSignal(client.from("messages").select(selected)
    .eq("conversation_id", input.conversation_id).eq("is_recalled", false)
    .in("role", [...CUSTOMER]).lte("created_at", input.source_created_at));
  const notes = new Set<string>();
  try {
    result.read_count++;
    const scoped = await withSignal(client.from("conversations").select("id,company_id")
      .eq("id", input.conversation_id).eq("company_id", input.company_id)).maybeSingle();
    if (scoped.error || scoped.data?.id !== input.conversation_id || scoped.data?.company_id !== input.company_id) {
      return fail("conversation_scope_unverified");
    }
    result.read_count++;
    const source = await base().eq("id", input.source_message_id).maybeSingle();
    if (source.error || !validRow(source.data) || source.data.id !== input.source_message_id ||
      compareTime(source.data.created_at, input.source_created_at) !== 0 ||
      normalized(source.data.content) !== normalized(input.source_content ?? input.latest)) {
      return fail("source_message_unverified");
    }
    byId.set(source.data.id, source.data);
    result.source_verified = true;
    result.usable_source_message_ids = [source.data.id];

    const persisted = record(input.memory);
    const memory = record(persisted?.memory) ?? persisted;
    const memoryScope = memory?.conversation_id === input.conversation_id && memory?.company_id === input.company_id &&
      (!record(persisted?.memory) || persisted?.conversation_id === input.conversation_id && persisted?.company_id === input.company_id &&
        persisted?.source_message_id === memory?.source_message_id);
    if (memory && !memoryScope) notes.add("memory_scope_unverified");
    const memorySource = memoryScope ? clean(memory?.source_message_id) : "";
    const anchors = memoryScope ? factualReadAnchors(memory?.factual_read_anchors) : [];
    const requested = distinct((input.requested_source_message_ids ?? []).map(clean));
    const ids = distinct([memorySource, ...requested, ...anchors.flatMap(anchor =>
      [anchor.source_message_id, ...anchor.subject_source_message_ids])]).filter(id => id !== input.source_message_id);
    if (ids.length > SEMANTIC_HISTORY_RECOVERY_LIMITS.source_ids) notes.add("source_id_budget");
    if (ids.length) {
      result.read_count++;
      const loaded = await base().in("id", ids.slice(0, SEMANTIC_HISTORY_RECOVERY_LIMITS.source_ids))
        .limit(SEMANTIC_HISTORY_RECOVERY_LIMITS.source_ids);
      if (loaded.error || !Array.isArray(loaded.data)) notes.add("source_read_failed");
      else for (const row of loaded.data) if (validRow(row)) byId.set(row.id, row);
    }
    result.memory_source_verified = Boolean(memorySource && byId.has(memorySource));
    if (memorySource && !result.memory_source_verified) notes.add("memory_source_unverified");
    if (requested.some(id => !byId.has(id))) notes.add("requested_source_unavailable");

    // A recalled or future snapshot cannot supply anchors or search hints.
    const verifiedAnchors = result.memory_source_verified ? anchors.filter(anchor => {
      const raw = byId.get(anchor.source_message_id);
      return raw && compareTime(raw.created_at, anchor.created_at) === 0 &&
        normalized(raw.content).startsWith(normalized(anchor.customer_text));
    }) : [];
    if (result.memory_source_verified && verifiedAnchors.length !== anchors.length) notes.add("anchor_source_unavailable");
    const recentIds = new Set(input.recent_history.filter(validRow).map(row => row.id));
    recentIds.add(input.source_message_id);
    const candidates = new Map<string, RecoveredCustomerHistoryRow>();
    const add = (row: RecoveredCustomerHistoryRow) => {
      byId.set(row.id, row);
      if (!recentIds.has(row.id)) candidates.set(row.id, row);
    };
    // Source reads can restore both an old locating question and a later scoped
    // correction. Preserve their actual chronology; do not infer replacement.
    const verifiedAnchorIds = new Set(verifiedAnchors.flatMap(anchor => [anchor.source_message_id, ...anchor.subject_source_message_ids]));
    for (const row of byId.values()) if (verifiedAnchorIds.has(row.id) || requested.includes(row.id)) add(row);

    const terms = locatingTerms(input.latest, input.search_terms ?? [], verifiedAnchors);
    const cjkTerms = cjkLocatingFragments(input.latest);
    const explicitAnchor = verifiedAnchors.some(anchor => anchor.subjects.some(subject => normalized(input.latest).includes(normalized(subject))));
    const contextual = mayNeedHistoricalContext(input.latest);
    const missingRecentAnchors = verifiedAnchors.some(anchor => !recentIds.has(anchor.source_message_id));
    const lifecycleIncomplete = result.memory_source_verified && memory?.question_lifecycle_incomplete === true;
    const indexIncomplete = result.memory_source_verified && memory?.factual_read_anchors_incomplete === true || lifecycleIncomplete;
    if (lifecycleIncomplete) notes.add("memory_question_lifecycle_incomplete");
    const shouldRecover = Boolean((input.search_terms?.length ?? 0) ||
      requested.some(id => !recentIds.has(id)) || contextual &&
        (!verifiedAnchors.length || missingRecentAnchors || indexIncomplete));
    const needsScan = shouldRecover && (!verifiedAnchors.length || indexIncomplete ||
      !explicitAnchor && /(?:之前|先前|最初|原先|上次|頭先|头先|前者|後者|后者)|\b(?:earlier|previous|first|second|original|former|latter|back)\b/iu.test(input.latest));
    let historyReads = 0;
    if (needsScan || (input.search_terms?.length ?? 0) > 0) {
      const searches = [...terms.map(term => ({term, cjk: false})),
        ...(cjkTerms.length ? [{term: "", cjk: true}] : [])].slice(0, SEMANTIC_HISTORY_RECOVERY_LIMITS.search_queries);
      for (const search of searches) {
        if (historyReads >= SEMANTIC_HISTORY_RECOVERY_LIMITS.history_queries) break;
        result.read_count++; historyReads++;
        const escaped = search.term.replace(/[\\%_]/gu, "\\$&");
        // Only Han fragments produced above enter this OR expression: no
        // customer punctuation or untrusted filter syntax is interpolated.
        const query = search.cjk
          ? base().or(cjkTerms.map(term => `content.ilike.*${term}*`).join(","))
          : base().ilike("content", `%${escaped}%`);
        const found = await query
          .order("created_at", {ascending: false}).order("id", {ascending: false})
          .limit(SEMANTIC_HISTORY_RECOVERY_LIMITS.page_size);
        if (found.error || !Array.isArray(found.data)) notes.add("history_search_failed");
        else {
          result.scanned_rows += found.data.length;
          for (const row of found.data) if (validRow(row)) add(row);
          if (found.data.length === SEMANTIC_HISTORY_RECOVERY_LIMITS.page_size) notes.add("search_result_bounded");
        }
      }
    }
    if (needsScan) {
      // Keyset pagination is bounded to customer turns before the oldest recent
      // customer row. It is on-demand, never a recurring 500-turn rebuild.
      const recent = input.recent_history.filter(row => validRow(row)) as RecoveredCustomerHistoryRow[];
      let cursor = [...recent, source.data].sort(compareMessageChronology)[0];
      let exhausted = false;
      while (historyReads < SEMANTIC_HISTORY_RECOVERY_LIMITS.history_queries) {
        const filter = olderThanFilter(cursor);
        if (!filter) { notes.add("history_cursor_unavailable"); break; }
        result.read_count++; historyReads++;
        const page = await base().or(filter).order("created_at", {ascending: false})
          .order("id", {ascending: false}).limit(SEMANTIC_HISTORY_RECOVERY_LIMITS.page_size);
        if (page.error || !Array.isArray(page.data)) { notes.add("history_read_failed"); break; }
        result.scanned_rows += page.data.length;
        const rows = page.data.filter(validRow) as RecoveredCustomerHistoryRow[];
        for (const row of rows) add(row);
        if (page.data.length < SEMANTIC_HISTORY_RECOVERY_LIMITS.page_size) { exhausted = true; break; }
        const next = rows.at(-1);
        if (!next || next.id === cursor.id) { notes.add("history_cursor_unavailable"); break; }
        cursor = next;
      }
      if (!exhausted) notes.add("history_scan_bounded");
    }

    const anchorIds = new Set(verifiedAnchors.flatMap(anchor => [anchor.source_message_id, ...anchor.subject_source_message_ids]));
    const sourcePriority = new Set(requested);
    const rank = (row: RecoveredCustomerHistoryRow): number =>
      (sourcePriority.has(row.id) ? 100 : 0) + (anchorIds.has(row.id) ? 60 : 0) +
      [...terms, ...cjkTerms].reduce((score, term) => score + (normalized(row.content).includes(normalized(term)) ? 15 : 0), 0);
    const ordered = [...candidates.values()].sort((a, b) => rank(b) - rank(a) || compareMessageChronology(a, b));
    let chars = 0;
    for (const row of ordered) {
      const size = row.content.length + row.id.length + row.created_at.length + 80;
      if (result.rows.length >= SEMANTIC_HISTORY_RECOVERY_LIMITS.output_rows || chars + size > SEMANTIC_HISTORY_RECOVERY_LIMITS.output_chars) {
        notes.add("recovered_context_bounded"); continue;
      }
      result.rows.push(row); chars += size;
    }
    result.rows.sort(compareMessageChronology);
    if (shouldRecover && !result.rows.length && !verifiedAnchors.length &&
      !input.recent_history.some(row => row.id !== input.source_message_id && CUSTOMER.has(String(row.role ?? ""))) &&
      /(?:之前|先前|最初|原先|頭先|头先|嗰|前者|後者|后者)|\b(?:earlier|previous|former|latter|first|second|back|it|that)\b/iu.test(input.latest)) notes.add("reference_not_recovered");
    result.usable_source_message_ids = [...byId.keys()];
    result.candidate_source_message_ids = result.rows.map(row => row.id);
    result.context_incomplete = notes.size > 0;
    result.reason = [...notes].join(",") || (result.rows.length ? "customer_sources_recovered" : "recent_context");
    return result;
  } catch {
    // Any source not successfully read remains unusable. Never turn a storage
    // failure into a fabricated older referent or a missing-KB assertion.
    result.usable_source_message_ids = [...byId.keys()];
    return fail(input.signal?.aborted ? "history_recovery_timeout" : "history_recovery_unavailable");
  }
}

import { uatRun } from "./uat-execution-contract.ts";
import { verifyQueryEmbeddingEvidence, prepareLiveMetadata } from "./preview-kb-query-embedding.ts";
import {
  originalPreviewKBRemoteScope,verifyOriginalPreviewKBRemoteProof,verifyOriginalPreviewKBLiveProof,prepareOriginalPreviewKBApiAdmission,type OriginalPreviewKBPermit,
  type AccountingRpc,
  ModelAccountingError,
  sha256,
} from "./model-attempt-accounting.ts";
export function remoteAccountingSecret(
  credential: { kind: string; value: string },
  cfg: { signingSecret?: string },
): string {
  return credential.kind === "jwt"
    ? (cfg.signingSecret ?? credential.value)
    : credential.value;
}
export interface RemoteScope {
  company: string;
  tenant: string;
  operation: string;
  expires: number;
  nonce: string;
  service?: "kb" | "coach_sync";
  request_sha256?: string;
}
const encoder = new TextEncoder();
export async function signRemote(
  value: string,
  secret: string,
): Promise<string> {
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  return Array.from(
    new Uint8Array(
      await crypto.subtle.sign("HMAC", key, encoder.encode(value)),
    ),
    (v) => v.toString(16).padStart(2, "0"),
  ).join("");
}
export async function verifyRemote(
  value: string,
  signature: string,
  secret: string,
): Promise<boolean> {
  if (!/^[a-f0-9]{64}$/.test(signature)) return false;
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["verify"],
  );
  return await crypto.subtle.verify(
    "HMAC",
    key,
    new Uint8Array(signature.match(/../g)!.map((v) => parseInt(v, 16))),
    encoder.encode(value),
  );
}
/** A retrieval HTTP request is not an attempt. Unknown downstream coverage denies before retrieval. */
export async function prepareRemoteRetrieval(
  company: string | null,
  tenant: string,
  credential: string,
  endpoint: string,
  upstream: typeof fetch = fetch,
  signal?: AbortSignal,
  service: "kb" | "coach_sync" = "kb",
  requestBody?: string,
  admittedMode?: "legacy" | "uat" | "authenticated_preview" | "authenticated_inbox",
  originalPermit?:OriginalPreviewKBPermit,
): Promise<Record<string, string>> {
  // Only accountedModelFetch supplies admittedMode after persisted identity and
  // provider checks. Existing callers keep their prior scope. Never turn a
  // Company UUID into a Synthetic UAT classification for an original Preview.
  const original=service==="kb" && (admittedMode==="authenticated_preview" || admittedMode==="authenticated_inbox");
  if(service==="kb" && admittedMode==="legacy")return {};
  if(!original) {
    if (company !== "4e0ea9f6-11d5-4968-97f6-f0ed8bf7cfec") return {};
    if (service === "kb") { uatRun(company); return {}; }
  }
  if(original && (!company || !requestBody))throw new ModelAccountingError("UAT_REMOTE_BOUND_UNVERIFIED");
  const permitted=original ? originalPreviewKBRemoteScope(originalPermit,company,tenant,endpoint,requestBody) : null;
  if(original && !permitted)throw new ModelAccountingError("UAT_REMOTE_BOUND_UNVERIFIED");
  if(original && permitted?.apiPolicy){
    if(!prepareOriginalPreviewKBApiAdmission(originalPermit))throw new ModelAccountingError("UAT_REMOTE_BOUND_UNVERIFIED");
    // Existing authenticated RAG POST only. Publication/version/chunk authority
    // must come from that response; no new control-plane credential or request.
    return {};
  }
  if(original && permitted?.livePolicy){
    const session=await prepareLiveMetadata(permitted.livePolicy,credential,upstream,signal);
    if(!verifyOriginalPreviewKBLiveProof(originalPermit,session))throw new ModelAccountingError("UAT_REMOTE_BOUND_UNVERIFIED");
    return {};
  }
  if(original && permitted?.evidence) {
    // Separately approved legacy query-embedding compatibility: verify existing
    // operator evidence offline, not a fictional retrieval_only remote route.
    // No remote I/O occurs here; the single original RAG POST follows only
    // after this opaque permit is consumed by accountedModelFetch.
    const attestation=await verifyQueryEmbeddingEvidence(permitted.evidence,credential);
    if(!verifyOriginalPreviewKBRemoteProof(originalPermit,permitted.runtime,attestation))throw new ModelAccountingError("UAT_REMOTE_BOUND_UNVERIFIED");
    return {};
  }
  const scope: RemoteScope = {
    company:company!,
    tenant,
    operation: `${service}:${crypto.randomUUID()}`,
    expires: Math.floor(Date.now() / 1000) + 60,
    nonce: crypto.randomUUID(),
    service,
    ...(original ? {request_sha256:await sha256(requestBody!)} : {}),
  };
  const payload = JSON.stringify(scope);
  const signature = await signRemote(payload, credential);
  let response: Response;
  try {
    response = await upstream(
      `${endpoint.replace(/\/$/, "")}/model-accounting-contract`,
      {
        method: "GET",
        redirect: "error",
        headers: {
          "x-ai-company-id": company!,
          "x-c3-accounting-scope": payload,
          "x-c3-accounting-signature": signature,
        },
        signal: signal
          ? AbortSignal.any([signal, AbortSignal.timeout(5000)])
          : AbortSignal.timeout(5000),
      },
    );
  } catch {
    throw new ModelAccountingError(original ? "UAT_REMOTE_BOUND_UNVERIFIED" : "KB_DOWNSTREAM_ACCOUNTING_UNAVAILABLE");
  }
  if (!response.ok) {
    throw new ModelAccountingError(original ? "UAT_REMOTE_BOUND_UNVERIFIED" : "KB_DOWNSTREAM_ACCOUNTING_UNPROVEN");
  }
  const text = await response.text();
  if (
    !await verifyRemote(
      text,
      response.headers.get("x-c3-accounting-signature") ?? "",
      credential,
    )
  ) throw new ModelAccountingError(original ? "UAT_REMOTE_BOUND_UNVERIFIED" : "KB_DOWNSTREAM_ACCOUNTING_UNPROVEN");
  let body: any;
  try {
    body = JSON.parse(text);
  } catch {
    throw new ModelAccountingError(original ? "UAT_REMOTE_BOUND_UNVERIFIED" : "KB_DOWNSTREAM_ACCOUNTING_UNPROVEN");
  }
  if (
    body.protocol !== "c3-shared-attempt-v1" || body.nonce !== scope.nonce ||
    body.company !== company || body.tenant !== tenant ||
    body.expires !== scope.expires || body.operation !== scope.operation ||
    body.service !== scope.service ||
    body.request_sha256 !== scope.request_sha256 ||
    !["retrieval_only", "shared_atomic_attempts"].includes(body.mode) ||
    !/^[a-f0-9]{64}$/.test(body.runtime_sha256 ?? "")
  ) {
    throw new ModelAccountingError(original ? "UAT_REMOTE_BOUND_UNVERIFIED" : "KB_DOWNSTREAM_ACCOUNTING_UNPROVEN");
  }
  // The synthetic shared-attempt callback does not authorize original Preview.
  // Even a signed remote 200 cannot opt that scope into a different paid run.
  // Current B-O is Vertex-only and denies before this preparation is called.
  if(original && (body.mode!=="retrieval_only" || body.runtime_sha256!==permitted!.runtime || !verifyOriginalPreviewKBRemoteProof(originalPermit,body.runtime_sha256)))throw new ModelAccountingError("UAT_REMOTE_BOUND_UNVERIFIED");
  return {
    "x-ai-company-id": company!,
    "x-c3-accounting-scope": payload,
    "x-c3-accounting-signature": signature,
    "x-c3-accounting-mode": body.mode,
  };
}
export async function remoteAccountingAction(
  db: AccountingRpc,
  scope: RemoteScope,
  body: Record<string, any>,
) {
  if (
    !Number.isInteger(scope.expires) ||
    scope.company !== "4e0ea9f6-11d5-4968-97f6-f0ed8bf7cfec" ||
    scope.expires < Math.floor(Date.now() / 1000) ||
    scope.expires > Math.floor(Date.now() / 1000) + 65
  ) {
    throw new ModelAccountingError("REMOTE_SCOPE_DENIED");
  }
  if (
    typeof body.identity !== "string" || !/^[a-f0-9]{64}$/.test(body.identity)
  ) throw new ModelAccountingError("REMOTE_IDENTITY_INVALID");
  // Signed operation prefix prevents a remote caller finalizing another operation's reservation.
  const identity = `${scope.operation}:${body.identity}`;
  let result;
  if (body.action === "reserve") {
    result = await db.rpc("c3_reserve_model_attempt", {
      p_company_id: scope.company,
      p_conversation_id: null,
      p_identity: identity,
      p_operation_id: scope.operation,
      p_provider: `${scope.service ?? "kb"}:${
        String(body.provider ?? "").slice(0, 100)
      }`,
      p_purpose: `${scope.service ?? "kb"}_downstream`,
      p_request_sha256: body.request_sha256,
      p_run_id: "a0a8c36e-42b5-4d9f-bbee-095ddc731520",
    });
  } else if (body.action === "finalize") {
    result = await db.rpc("c3_finalize_model_attempt", {
      p_company_id: scope.company,
      p_run_id: "a0a8c36e-42b5-4d9f-bbee-095ddc731520",
      p_identity: identity,
      p_state: body.state,
      p_http_status: body.http_status,
    });
  } else throw new ModelAccountingError("REMOTE_ACTION_DENIED");
  if (result.error || !result.data) {
    throw new ModelAccountingError("REMOTE_ACCOUNTING_DENIED");
  }
  return result.data;
}

/** Phase-2 Coach is excluded only from the Director-authorized Phase-1 synthetic run. */
export function phase1CoachAllowed(company: string, enabled: boolean): boolean {
  return enabled && company !== "4e0ea9f6-11d5-4968-97f6-f0ed8bf7cfec";
}

// supabase/functions/_shared/kb-auth.ts
// Server-only Singapore KB credential resolver.
//
// Data-plane/RAG contract:
//   opaque tenant-bound API key -> x-api-key
// Control-plane contract (CRUD / publish / migration):
//   Singapore service-role secret -> x-service-role-secret (preferred)
//   Base44-compatible SINGAPORE_BACKEND_TOKEN -> Authorization: Bearer (fallback)
//   tenant-bound service JWT/token is retained only as an explicit legacy fallback.
//
// Browser payloads never choose company/tenant/key scope.

export type KBAuthHeaderMode = "authorization" | "x-api-key";
export type KBScopeMode = "canonical" | "pre_activation" | "demo";

export interface KBCredentialScope {
  mode: KBScopeMode;
  aiCompanyId: string | null;
  singaporeTenantId: string;
}

export interface KBCredentialConfig {
  signingSecret?: string;
  jwtTtlSec: number;
  defaultToken?: string;
  tenantTokens: Record<string, string>;
  tenantApiKeys: Record<string, string>;
  apiKeyHeaderMode: KBAuthHeaderMode;
}

export type KBCredential =
  | { ok: true; kind: "api_key" | "jwt" | "bearer" | "service_role"; value: string }
  | { ok: false; error_code: string };

function decodeJwtPayload(token: string): Record<string, unknown> | null {
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  try {
    const b64 = parts[1].replace(/-/g, "+").replace(/_/g, "/");
    const padded = b64 + "=".repeat((4 - (b64.length % 4 || 4)) % 4);
    const parsed = JSON.parse(atob(padded));
    return parsed && typeof parsed === "object" && !Array.isArray(parsed)
      ? parsed as Record<string, unknown>
      : null;
  } catch {
    return null;
  }
}

function base64UrlEncode(bytes: Uint8Array): string {
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary)
    .replace(/\+/g, "-")
    .replace(/\//g, "_")
    .replace(/=+$/g, "");
}

function base64UrlJson(value: Record<string, unknown>): string {
  return base64UrlEncode(
    new TextEncoder().encode(JSON.stringify(value)),
  );
}

async function mintSingaporeTenantJwt(
  scope: KBCredentialScope,
  cfg: KBCredentialConfig,
): Promise<string | null> {
  if (!cfg.signingSecret) return null;

  const now = Math.floor(Date.now() / 1000);
  const header = base64UrlJson({ alg: "HS256", typ: "JWT" });
  const actorRef = scope.mode === "canonical" && scope.aiCompanyId
    ? `company:${scope.aiCompanyId}`
    : scope.mode === "pre_activation"
      ? "pre-activation"
      : "demo";
  const payload = base64UrlJson({
    sub: `ai-chatbot:${actorRef}`,
    tenant_id: scope.singaporeTenantId,
    role: "service",
    iat: now,
    exp: now + cfg.jwtTtlSec,
  });
  const signingInput = `${header}.${payload}`;
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(cfg.signingSecret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign(
    "HMAC",
    key,
    new TextEncoder().encode(signingInput),
  );
  return `${signingInput}.${base64UrlEncode(new Uint8Array(signature))}`;
}

function validOpaqueCredential(value: string): boolean {
  if (value.length < 16 || value.length > 4096) return false;
  return !/[\r\n\0]/.test(value);
}

function validateTenantJwt(
  scope: KBCredentialScope,
  token: string,
  missingCode: string,
): KBCredential {
  if (!token) return { ok: false, error_code: missingCode };
  const claims = decodeJwtPayload(token);
  if (!claims) return { ok: false, error_code: "KB_AUTH_TOKEN_INVALID" };

  const tokenTenant = claims.tenant_id ?? claims.sub;
  if (String(tokenTenant ?? "") !== scope.singaporeTenantId) {
    return { ok: false, error_code: "KB_AUTH_TENANT_MISMATCH" };
  }

  const exp = Number(claims.exp);
  if (Number.isFinite(exp) && exp * 1000 <= Date.now() + 5000) {
    return { ok: false, error_code: "KB_AUTH_TOKEN_EXPIRED" };
  }
  return { ok: true, kind: "jwt", value: token };
}

function resolveServiceRoleSecret(): string {
  return (
    Deno.env.get("SINGAPORE_SERVICE_ROLE_SECRET")?.trim() ||
    Deno.env.get("KB_SINGAPORE_SERVICE_ROLE_SECRET")?.trim() ||
    Deno.env.get("SERVICE_ROLE_SECRET")?.trim() ||
    ""
  );
}

/**
 * Resolve the Singapore RAG/data-plane credential.
 * Production prefers the tenant-scoped opaque x-api-key. JWT remains a
 * documented rollback/data-plane option only.
 */
export async function resolveSingaporeCredential(
  scope: KBCredentialScope,
  cfg: KBCredentialConfig,
): Promise<KBCredential> {
  const apiKey = cfg.tenantApiKeys[scope.singaporeTenantId]?.trim();
  if (apiKey) {
    if (!validOpaqueCredential(apiKey)) {
      return { ok: false, error_code: "KB_AUTH_API_KEY_INVALID" };
    }
    return { ok: true, kind: "api_key", value: apiKey };
  }

  const minted = await mintSingaporeTenantJwt(scope, cfg);
  const token = minted ??
    cfg.tenantTokens[scope.singaporeTenantId] ??
    cfg.defaultToken ?? "";
  return validateTenantJwt(scope, token, "KB_AUTH_TOKEN_MISSING");
}

/**
 * Resolve the Singapore control-plane credential for entity CRUD, publish and
 * migration operations.
 *
 * Current Singapore Base44-parity APIs expose two server-to-server control
 * authentication surfaces: x-service-role-secret and Authorization Bearer.
 * Prefer the dedicated service-role secret because it does not require moving
 * the Singapore JWT signing authority or inventing client-side JWT claims.
 *
 * Base44's SINGAPORE_BACKEND_TOKEN Bearer contract remains a supported fallback.
 * RAG tenant API keys are NEVER considered on this mutation path.
 */
export async function resolveSingaporeControlCredential(
  scope: KBCredentialScope,
  cfg: KBCredentialConfig,
): Promise<KBCredential> {
  const serviceRoleSecret = resolveServiceRoleSecret();
  if (serviceRoleSecret) {
    if (!validOpaqueCredential(serviceRoleSecret)) {
      return { ok: false, error_code: "KB_AUTH_CONTROL_SERVICE_SECRET_INVALID" };
    }
    return { ok: true, kind: "service_role", value: serviceRoleSecret };
  }

  const base44ControlToken = Deno.env.get("SINGAPORE_BACKEND_TOKEN")?.trim() ?? "";
  if (base44ControlToken) {
    if (!validOpaqueCredential(base44ControlToken)) {
      return { ok: false, error_code: "KB_AUTH_CONTROL_TOKEN_INVALID" };
    }
    return { ok: true, kind: "bearer", value: base44ControlToken };
  }

  const minted = await mintSingaporeTenantJwt(scope, cfg);
  const token = minted ??
    cfg.tenantTokens[scope.singaporeTenantId] ??
    cfg.defaultToken ?? "";
  const resolved = validateTenantJwt(scope, token, "KB_AUTH_CONTROL_CREDENTIAL_MISSING");
  if (!resolved.ok) return resolved;
  return { ok: true, kind: "jwt", value: resolved.value };
}

export function singaporeCredentialHeaders(
  credential: Extract<KBCredential, { ok: true }>,
  cfg: Pick<KBCredentialConfig, "apiKeyHeaderMode">,
): Record<string, string> {
  if (credential.kind === "service_role") {
    return { "x-service-role-secret": credential.value };
  }
  if (
    credential.kind === "api_key" &&
    cfg.apiKeyHeaderMode === "x-api-key"
  ) {
    return { "x-api-key": credential.value };
  }
  return { Authorization: `Bearer ${credential.value}` };
}

// supabase/functions/_shared/kb-aggregation-response.ts
// Strict parser for the Singapore KB aggregated RAG v1 response contract.
// Structured selected_documents[].evidence[] is authoritative for grounding.
// llm_context.combined_text is intentionally not used as factual evidence.
//
// Evidence is parsed and retained per document. Demand-aware callers may keep
// complementary sources after checking each source's authority and lineage;
// a single document's authority never applies to another document's evidence.

export type AggregationChunkType = "rag_summary" | "full_content" | "faq_pair" | "section";

export interface AggregationChunk {
  document_id: string;
  chunk_id?: string;
  title: string;
  source_type: string;
  content: string;
  score: number;
  chunk_type: AggregationChunkType;
}

export interface AggregationCitation {
  display_label: string;
  content: string;
  score: number;
  source_type: string;
  document_id: string;
  chunk_id?: string;
  chunk_type: AggregationChunkType;
}

export interface AggregationEvidence {
  document_id: string;
  chunk_id?: string;
  content: string;
  score: number;
  source_type: string;
}

export interface AggregationInternalContext {
  selected_document_id: string;
  orientation_summary: string | null;
  full_content_evidence: AggregationEvidence[];
}

export interface AggregationMeta {
  document_score: number;
  highest_chunk_score: number;
  second_highest_chunk_score: number;
  returned_summary_count: number;
  returned_full_content_count: number;
  dropped_without_document_id: number;
  dropped_without_content: number;
}

export interface AggregationAuthorityMetadata {
  tenant_id: string | null;
  publication_state: string | null;
  currentness: "current" | "historical" | "superseded" | "cancelled" | "unknown";
  entity_ids: string[];
  regions: string[];
  language: string | null;
  version: string | null;
  version_rank: number | null;
  updated_at: string | null;
  source_priority: number | null;
  claims: Array<{ key: string; value: string }>;
}

/** Runtime constructor shared by all KB adapters so authority metadata cannot drift by transport. */
export function createAggregationAuthorityMetadata(
  value: AggregationAuthorityMetadata,
): AggregationAuthorityMetadata {
  return {
    ...value,
    entity_ids: [...value.entity_ids],
    regions: [...value.regions],
    claims: value.claims.map((claim) => ({ ...claim })),
  };
}

export interface AggregationDocumentCandidate {
  document_id: string;
  title: string;
  source_type: string;
  document_score: number;
  chunks: AggregationChunk[];
  citations: AggregationCitation[];
  llm_context: AggregationInternalContext;
  meta: AggregationMeta;
  authority: AggregationAuthorityMetadata;
}

export type ParsedAggregationResponse =
  | {
      ok: true;
      contextFound: false;
      chunks: [];
      citations: [];
      documents: [];
    }
  | {
      ok: true;
      contextFound: true;
      chunks: AggregationChunk[];
      citations: AggregationCitation[];
      documents: AggregationDocumentCandidate[];
    }
  | { ok: false; error_code: string };

type Obj = Record<string, unknown>;
const MAX_SELECTED_DOCUMENTS = 5;
const MAX_SUMMARY_CHUNKS_PER_DOCUMENT = 1;
const MAX_FULL_CONTENT_CHUNKS_PER_DOCUMENT = 3;

function isObj(v: unknown): v is Obj {
  return !!v && typeof v === "object" && !Array.isArray(v);
}
function finite(v: unknown): number | null {
  const n = typeof v === "number" ? v : Number(v);
  return Number.isFinite(n) ? n : null;
}
function nonEmpty(v: unknown): string | null {
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

function stringArray(value: unknown, maxItems = 24, maxLength = 160): string[] {
  if (!Array.isArray(value)) return [];
  return [
    ...new Set(
      value
        .filter((item): item is string => typeof item === "string")
        .map((item) => item.normalize("NFKC").trim().slice(0, maxLength))
        .filter(Boolean),
    ),
  ].slice(0, maxItems);
}

function authorityMetadata(doc: Obj): AggregationAuthorityMetadata {
  const metadata = isObj(doc.authority) ? doc.authority : isObj(doc.metadata) ? doc.metadata : {};
  const first = (...values: unknown[]) => values.map(nonEmpty).find(Boolean) ?? null;
  const firstIdentifier = (...values: unknown[]) => {
    for (const value of values) {
      const parsed =
        nonEmpty(value) ??
        (typeof value === "number" && Number.isSafeInteger(value) ? String(value) : null);
      if (parsed) return parsed;
    }
    return null;
  };
  const currentRaw = first(
    metadata.currentness,
    metadata.freshness_status,
    doc.currentness,
    doc.freshness_status,
  )?.toLowerCase();
  const explicitCurrent =
    typeof metadata.is_current === "boolean"
      ? metadata.is_current
      : typeof doc.is_current === "boolean"
        ? doc.is_current
        : null;
  const currentness =
    currentRaw === "historical" ||
    currentRaw === "superseded" ||
    currentRaw === "cancelled" ||
    currentRaw === "current"
      ? currentRaw
      : explicitCurrent === false
        ? "historical"
        : explicitCurrent === true
          ? "current"
          : "unknown";
  const rawClaims = Array.isArray(metadata.claims)
    ? metadata.claims
    : Array.isArray(doc.claims)
      ? doc.claims
      : [];
  const claims = rawClaims
    .flatMap((claim): Array<{ key: string; value: string }> => {
      if (!isObj(claim)) return [];
      const key = first(claim.key, claim.fact_key);
      const value = first(claim.value, claim.fact_value);
      return key && value ? [{ key: key.slice(0, 200), value: value.slice(0, 500) }] : [];
    })
    .slice(0, 24);
  const versionRank = finite(
    metadata.version_rank ?? metadata.version_number ?? doc.version_rank ?? doc.version_number,
  );
  const sourcePriority = finite(metadata.source_priority ?? doc.source_priority);
  return {
    tenant_id: firstIdentifier(
      metadata.tenant_id,
      metadata.company_id,
      doc.tenant_id,
      doc.company_id,
    ),
    publication_state: first(
      metadata.publication_state,
      metadata.status,
      doc.publication_state,
      doc.status,
    ),
    currentness,
    entity_ids: stringArray(metadata.entity_ids ?? metadata.models ?? doc.entity_ids ?? doc.models),
    regions: stringArray(
      metadata.regions ?? metadata.markets ?? doc.regions ?? doc.markets,
      12,
      80,
    ),
    language: first(metadata.language, doc.language),
    version: first(metadata.version, metadata.version_id, doc.version, doc.version_id),
    version_rank: versionRank,
    updated_at: first(metadata.updated_at, metadata.published_at, doc.updated_at, doc.published_at),
    source_priority: sourcePriority,
    claims,
  };
}

function parseDocumentCandidate(doc: unknown): AggregationDocumentCandidate | null {
  if (!isObj(doc)) return null;

  const documentId = nonEmpty(doc.document_id);
  const title = nonEmpty(doc.title) ?? "Knowledge Base document";
  const sourceType = nonEmpty(doc.source_type) ?? "knowledge";
  const documentScore = finite(doc.document_score);
  if (!documentId || documentScore === null || !Array.isArray(doc.evidence)) {
    return null;
  }

  const chunks: AggregationChunk[] = [];
  const citations: AggregationCitation[] = [];
  const fullEvidence: AggregationEvidence[] = [];
  const scores: number[] = [];
  let orientationSummary: string | null = null;

  if (doc.summary !== null && doc.summary !== undefined) {
    if (!isObj(doc.summary)) return null;
    const content = nonEmpty(doc.summary.content);
    const score = finite(doc.summary.score);
    const chunkId = nonEmpty(doc.summary.chunk_id) ?? undefined;
    if (!content || score === null || doc.summary.chunk_type !== "rag_summary") return null;

    orientationSummary = content;
    scores.push(score);
    chunks.push({
      document_id: documentId,
      ...(chunkId ? { chunk_id: chunkId } : {}),
      title,
      source_type: sourceType,
      content,
      score,
      chunk_type: "rag_summary",
    });
    citations.push({
      display_label: title.slice(0, 200),
      content: content.slice(0, 500),
      score,
      source_type: sourceType,
      document_id: documentId,
      ...(chunkId ? { chunk_id: chunkId } : {}),
      chunk_type: "rag_summary",
    });
  }

  let fullCount = 0;
  let summaryCount = orientationSummary ? 1 : 0;
  for (const item of doc.evidence) {
    if (!isObj(item)) return null;
    const content = nonEmpty(item.content);
    const score = finite(item.score);
    const chunkId = nonEmpty(item.chunk_id) ?? undefined;
    const chunkType = item.chunk_type;
    if (
      !content ||
      score === null ||
      (chunkType !== "rag_summary" &&
        chunkType !== "full_content" &&
        chunkType !== "faq_pair" &&
        chunkType !== "section")
    )
      return null;

    if (chunkType === "rag_summary") {
      summaryCount += 1;
      if (summaryCount > MAX_SUMMARY_CHUNKS_PER_DOCUMENT) return null;
      orientationSummary = content;
    }
    if (chunkType === "full_content") {
      fullCount += 1;
      if (fullCount > MAX_FULL_CONTENT_CHUNKS_PER_DOCUMENT) return null;
      fullEvidence.push({
        document_id: documentId,
        ...(chunkId ? { chunk_id: chunkId } : {}),
        content,
        score,
        source_type: sourceType,
      });
    }

    scores.push(score);
    chunks.push({
      document_id: documentId,
      ...(chunkId ? { chunk_id: chunkId } : {}),
      title,
      source_type: sourceType,
      content,
      score,
      chunk_type: chunkType as AggregationChunkType,
    });
    citations.push({
      display_label: title.slice(0, 200),
      content: content.slice(0, 500),
      score,
      source_type: sourceType,
      document_id: documentId,
      ...(chunkId ? { chunk_id: chunkId } : {}),
      chunk_type: chunkType as AggregationChunkType,
    });
  }

  if (chunks.length === 0) return null;
  scores.sort((a, b) => b - a);

  return {
    document_id: documentId,
    title,
    source_type: sourceType,
    document_score: documentScore,
    chunks,
    citations,
    llm_context: {
      selected_document_id: documentId,
      orientation_summary: orientationSummary,
      full_content_evidence: fullEvidence,
    },
    meta: {
      document_score: documentScore,
      highest_chunk_score: scores[0] ?? 0,
      second_highest_chunk_score: scores[1] ?? 0,
      returned_summary_count: orientationSummary ? 1 : 0,
      returned_full_content_count: fullEvidence.length,
      dropped_without_document_id: 0,
      dropped_without_content: 0,
    },
    authority: authorityMetadata(doc),
  };
}

export function parseAggregationResponse(data: unknown): ParsedAggregationResponse {
  if (!isObj(data)) return { ok: false, error_code: "KB_SCHEMA_INVALID" };
  if (data.success !== true || typeof data.context_found !== "boolean") {
    return { ok: false, error_code: "KB_SCHEMA_INVALID" };
  }

  if (data.context_found === false) {
    if (!Array.isArray(data.selected_documents) || data.selected_documents.length !== 0) {
      return { ok: false, error_code: "KB_SCHEMA_INVALID" };
    }
    if (!Array.isArray(data.citations) || data.citations.length !== 0) {
      return { ok: false, error_code: "KB_SCHEMA_INVALID" };
    }
    if (data.llm_context !== undefined && data.llm_context !== null) {
      if (!isObj(data.llm_context)) {
        return { ok: false, error_code: "KB_SCHEMA_INVALID" };
      }
      const sc = finite(data.llm_context.summary_count);
      const ec = finite(data.llm_context.evidence_count);
      if (sc !== 0 || ec !== 0) {
        return { ok: false, error_code: "KB_SCHEMA_INVALID" };
      }
    }
    return {
      ok: true,
      contextFound: false,
      chunks: [],
      citations: [],
      documents: [],
    };
  }

  if (
    !Array.isArray(data.selected_documents) ||
    data.selected_documents.length < 1 ||
    data.selected_documents.length > MAX_SELECTED_DOCUMENTS
  ) {
    return { ok: false, error_code: "KB_SCHEMA_INVALID" };
  }

  const documents: AggregationDocumentCandidate[] = [];
  const seenDocumentIds = new Set<string>();
  for (const rawDoc of data.selected_documents) {
    const parsed = parseDocumentCandidate(rawDoc);
    if (!parsed || seenDocumentIds.has(parsed.document_id)) {
      return { ok: false, error_code: "KB_SCHEMA_INVALID" };
    }
    seenDocumentIds.add(parsed.document_id);
    documents.push(parsed);
  }

  return {
    ok: true,
    contextFound: true,
    documents,
    chunks: documents.flatMap((d) => d.chunks),
    citations: documents.flatMap((d) => d.citations),
  };
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.45.0";
import { getSupabaseAdminKey } from "./supabase-admin-key.ts";

const NONPRODUCTION_REF = "nbtowfuvvfqpxqydyoby";

export function isC3NonproductionProject(): boolean {
  try {
    return new URL(Deno.env.get("SUPABASE_URL") ?? "").hostname ===
      `${NONPRODUCTION_REF}.supabase.co`;
  } catch {
    return false;
  }
}
export async function resolveServerSecret(
  environmentName: string,
  nonproductionVaultName: string,
): Promise<string | null> {
  const configured = Deno.env.get(environmentName)?.trim();
  if (configured) return configured;
  if (!isC3NonproductionProject()) return null;
  const url = Deno.env.get("SUPABASE_URL") ?? "";
  let key = "";
  try {
    key = getSupabaseAdminKey();
  } catch {
    return null;
  }
  const sb = createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await sb.rpc("c3_nonprod_resolve_secret", {
    p_name: nonproductionVaultName,
  });
  return !error && typeof data === "string" && data.trim() ? data.trim() : null;
}

import { createClient, SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2.45.0";
import { json } from "./cors.ts";

export type Agent = {
  id: string;
  user_id: string;
  role: string;
  status: string;
  display_name: string;
};

export type AgentCompanyRole = "admin" | "supervisor" | "agent" | "qa";

export type AgentCompanyScope = {
  companyId: string;
  companyRole: AgentCompanyRole;
};

const COMPANY_ROLE_PRECEDENCE: AgentCompanyRole[] = [
  "admin",
  "supervisor",
  "agent",
  "qa",
];

export function getClients(req: Request): { supabaseAuth: SupabaseClient; supabaseAdmin: SupabaseClient } {
  const supabaseAuth = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_ANON_KEY")!,
    { global: { headers: { Authorization: req.headers.get("Authorization") ?? "" } } },
  );
  const supabaseAdmin = createClient(
    Deno.env.get("SUPABASE_URL")!,
    Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
  );
  return { supabaseAuth, supabaseAdmin };
}

export async function validateAgent(
  req: Request,
): Promise<{ agent: Agent; supabaseAdmin: SupabaseClient } | Response> {
  const { supabaseAuth, supabaseAdmin } = getClients(req);
  const { data: { user }, error: authError } = await supabaseAuth.auth.getUser();
  if (authError || !user) return json({ error: "Unauthorized" }, 401);

  const { data: agent, error: agentError } = await supabaseAdmin
    .from("agent_profile")
    .select("id, user_id, role, status, display_name")
    .eq("user_id", user.id)
    .single();
  if (agentError || !agent) return json({ error: "Agent profile not found" }, 403);
  if (agent.status !== "active") return json({ error: "Agent account is inactive" }, 403);
  if (!agent.user_id) return json({ error: "Agent identity is not linked" }, 403);

  return { agent: agent as Agent, supabaseAdmin };
}

/**
 * Resolve the single active company boundary for a signed-in agent.
 *
 * The current console has no explicit company-switch context, so ambiguous
 * multi-company membership is fail-closed rather than guessed.
 */
export async function resolveAgentCompanyScope(
  supabaseAdmin: SupabaseClient,
  agent: Agent,
): Promise<AgentCompanyScope | Response> {
  const { data: memberships, error: membershipError } = await supabaseAdmin
    .from("company_membership")
    .select("company_id, role")
    .eq("user_id", agent.user_id)
    .eq("is_active", true);

  if (membershipError) {
    console.error("[agent-scope] company membership lookup failed", membershipError.code);
    return json({ error: "Company scope lookup failed" }, 500);
  }

  const rows = (memberships ?? []) as { company_id: string; role: string }[];
  const companyIds = [...new Set(rows.map((row) => String(row.company_id)))];

  if (companyIds.length === 0) {
    return json({ error: "Company scope is not configured", error_type: "company_scope_unresolved" }, 403);
  }
  if (companyIds.length !== 1) {
    return json({ error: "Company scope is ambiguous", error_type: "company_scope_ambiguous" }, 409);
  }

  const companyId = companyIds[0];
  const roles = rows
    .filter((row) => String(row.company_id) === companyId)
    .map((row) => String(row.role) as AgentCompanyRole);

  const companyRole = COMPANY_ROLE_PRECEDENCE.find((candidate) => roles.includes(candidate));
  if (!companyRole) {
    return json({ error: "Company role is not configured", error_type: "company_role_unresolved" }, 403);
  }

  const { data: company, error: companyError } = await supabaseAdmin
    .from("company")
    .select("id, is_active")
    .eq("id", companyId)
    .maybeSingle();

  if (companyError) {
    console.error("[agent-scope] company lookup failed", companyError.code);
    return json({ error: "Company scope lookup failed" }, 500);
  }
  if (!company || company.is_active !== true) {
    return json({ error: "Company is inactive", error_type: "company_inactive" }, 403);
  }

  return { companyId, companyRole };
}

/**
 * Resolve a target agent only when that agent is active and belongs to the
 * actor's already-resolved company boundary.
 */
export async function validateTargetAgentInCompany(
  supabaseAdmin: SupabaseClient,
  targetAgentId: string,
  companyId: string,
): Promise<{ id: string; user_id: string; status: string; display_name: string } | Response> {
  const { data: target, error: targetError } = await supabaseAdmin
    .from("agent_profile")
    .select("id, user_id, status, display_name")
    .eq("id", targetAgentId)
    .maybeSingle();

  if (targetError) {
    console.error("[agent-scope] target agent lookup failed", targetError.code);
    return json({ error: "Target agent lookup failed" }, 500);
  }
  if (!target || !target.user_id) return json({ error: "Target agent not found" }, 404);
  if (target.status !== "active") return json({ error: "Target agent is not active" }, 400);

  const { data: membership, error: membershipError } = await supabaseAdmin
    .from("company_membership")
    .select("id")
    .eq("user_id", target.user_id)
    .eq("company_id", companyId)
    .eq("is_active", true)
    .limit(1)
    .maybeSingle();

  if (membershipError) {
    console.error("[agent-scope] target membership lookup failed", membershipError.code);
    return json({ error: "Target agent lookup failed" }, 500);
  }
  if (!membership) {
    // Deliberately 404 so callers cannot enumerate agents from other tenants.
    return json({ error: "Target agent not found" }, 404);
  }

  return target as { id: string; user_id: string; status: string; display_name: string };
}

