        "我明白你想核對門市或商品供應。目前我未有可核實的即時庫存；請提供完整產品名稱／型號、門市或地區及所需日期，我再按該範圍核對。",
        "我明白你想核对门店或商品供应。目前我没有可核实的实时库存；请提供完整产品名称／型号、门店或地区及所需日期，我再按该范围核对。",
        "I understand that you want to check store or product availability. I do not have verified live stock here. Please share the exact product/model, store or region, and required date so that specific scope can be checked.",
      ],
      marketplace_or_product_support: [
        "我明白商品或第三方賣家交付內容與預期不符。目前我不能核實訂單或賣家處理狀態；請提供訂單／參考編號、商品型號及不符之處，以便核對可行的下一步。",
        "我明白商品或第三方卖家交付内容与预期不符。目前我无法核实订单或卖家处理状态；请提供订单／参考编号、商品型号及不符之处，以便核对可行的下一步。",
        "I understand that the product or third-party seller outcome did not match what was expected. I cannot verify the live order or seller action here. Please share the order/reference number, product model, and the specific mismatch so the available next step can be checked.",
      ],
      general_customer_issue: [
        "我明白你遇到客戶服務問題。目前我不能核實即時帳戶、訂單或處理狀態；請提供相關訂單／個案參考編號及受影響項目，以便核對下一步。我不會在未有證據前聲稱任何處理已完成。",
        "我明白你遇到客户服务问题。目前我无法核实实时账户、订单或处理状态；请提供相关订单／个案参考编号及受影响项目，以便核对下一步。我不会在没有证据前声称任何处理已完成。",
        "I understand the customer-service issue. I cannot verify the live account, order, or case status here. Please share the relevant order/case reference and affected item so the next step can be checked; I will not claim that any action has completed without evidence.",
      ],
    };
    return responses[plan.issue_kind][l];
  }
  if (plan.action === "historical_calculation" && plan.calculation) {
    const c = plan.calculation;
    const perUnit = c.terms.filter((term) => term.charge_basis === "per_unit");
    const perOrder = c.terms.filter((term) =>
      term.charge_basis === "per_order"
    );
    const money = (amount: number) => `${c.currency === "HKD" ? "HK$" : c.currency === "USD" ? "US$" : c.currency} ${formatMoney(amount)}`;
    const unitExpression = perUnit.some(term=>term.amount !== 0)
      ? `(${perUnit.map((term) => money(term.amount)).join(" + ")}) × ${c.quantity}`
      : "";
    const expression = [unitExpression,...perOrder.filter(term=>term.amount !== 0).map(term=>money(term.amount))]
      .filter(Boolean).join(" + ") || money(0);
    const equation = `${expression} = ${money(c.total)}`;
    return [
      `按你提供嘅歷史金額（每部收費 × 部數，另加每單收費，如有）：${equation}。呢個只係歷史條件試算，唔代表現行正式報價或現價。`,
      `按你提供并已标明收费单位的旧数字：${equation}。这只是历史条件试算，不是当前正式报价。`,
      `Using only the historical amounts with an explicit charge basis: ${equation}. This is a conditional historical calculation using your figures only, not a current merchant offer.`,
    ][l];
  }
  if (plan.action === "shorten_previous_answer") {
    // generate-reply supplies newest-first message rows.
    const prior = recentMessages.find((item) =>
      item.role === "assistant" && clean(item.content)
    );
    if (!prior) return null;
    const previous = clean(prior.content, 1600);
    const amounts = [...previous.matchAll(/(?:HKD\s*)?\d[\d,]{2,}/g)]
      .map((match) => match[0].replace(/^HKD\s*/i, ""))
      .filter((value, index, all) => all.indexOf(value) === index);
    if (amounts.length && /(?:歷史|历史|舊價|旧价|非現價|非现价|不是現行報價|不是当前报价)/i.test(previous)) {
      const compact = amounts.slice(0, 2).join("／");
      if (/訂單尚未確認/.test(previous) && /仍需核實/.test(previous)) {
        return `HKD ${compact} 不是現行報價；訂單尚未確認，工程費仍需核實。`;
      }
      return /再短|even shorter/i.test(plan.customer_turn ?? "")
        ? `${compact}：舊價，非現價。`
        : `${compact} 係你提供嘅歷史價，唔係已核實現價。`;
    }
    const sentences = previous.split(/(?<=[。！？.!?])\s*/)
      .filter(Boolean);
    const safety = sentences.filter((sentence) =>
      /(?:不|未|尚未|不能|不可|並非|并非|唔|冇|沒有|没有|仍需|待核|核實|核实|not|isn't|is not|cannot|can't|unconfirmed|pending|subject to|限制|假設|假设)/i
        .test(sentence)
    );
    const selected = [...new Set([sentences[0], ...safety])].filter(Boolean);
    return selected.join(" ").slice(0, 600);
  }
  if (plan.action === "current_state_checklist") {
    const statusLabels: Record<string, string[]> = {
      confirmed: ["已確認", "已确认", "confirmed"],
      provided: [
        "已提供，待最終確認",
        "已提供，待最终确认",
        "provided, awaiting final confirmation",
      ],
      draft: ["草擬中", "草拟中", "draft"],
      not_started: ["尚未建立", "尚未建立", "not created"],
    };
    const known = plan.known_facts.slice(0, 6).map((fact) =>
      `• ${fact.label}：${fact.value}（${
        statusLabels[fact.status]?.[l] ?? statusLabels.provided[l]
      }）`
    );
    const missing = plan.missing_slots.map((slot) =>
      `• ${labels[slot]?.[l] ?? labels.customer_goal[l]}`
    );
    const heading =
      ["付款／落單前清單", "付款／下单前清单", "Pre-payment checklist"][l];
    return [heading, ...known, ...missing].join("\n").slice(0, 1600);
  }
  return null;
}

function planLanguageIndex(
  plan: ServiceDialoguePlan,
  messages: Array<{ role: string; content: string }>,
): number {
  void messages;
  return plan.language === "en" ? 2 : plan.language === "zh-CN" ? 1 : 0;
}

export function renderTargetedServiceQuestion(
  plan: ServiceDialoguePlan,
  language: ServiceLanguage,
): string {
  const l = language === "en" ? 2 : language === "zh-CN" ? 1 : 0;
  if (plan.action === "explicit_handoff") {
    return [
      "收到你想聯絡真人客服的要求；目前尚未完成交接，請等候系統確認。",
      "收到你想联系人工客服的要求；目前尚未完成交接，请等候系统确认。",
      "I understand that you want human support. The handoff is not complete yet; please wait for the system confirmation.",
    ][l];
  }
  if (plan.action === "offer_handoff_or_reframe") {
    return [
      "目前未有新的關鍵資料，我不想重複問同一問題。你可以提供更具體的型號／項目，或選擇由真人客服接手；目前尚未執行轉交。",
      "目前没有新的关键资料，我不想重复问同一问题。你可以提供更具体的型号／项目，或选择由人工客服接手；目前尚未执行转交。",
      "We still do not have a new decision-making detail, so I will not repeat the same question. You can share the specific model or item, or choose human support; no handoff has been performed yet.",
    ][l];
  }
  const target = plan.clarification_target ?? plan.missing_slots[0] ??
    "customer_goal";
  const question = labels[target]?.[l] ?? labels.customer_goal[l];
  const empathy = plan.emotion_trace?.kind &&
      /(?:frustrat|angry|disappoint|失望|憤怒|愤怒)/i.test(
        plan.emotion_trace.kind,
      )
    ? [
      "我明白這個情況令人失望。",
      "我明白这个情况令人失望。",
      "I understand that this situation is frustrating.",
    ][l]
    : "";
  return `${empathy}${empathy ? " " : ""}${question}`;
}

export function applyServiceTone(
  plan: ServiceDialoguePlan,
  reply: string | null,
): string | null {
  if (
    !reply || !plan.emotion_trace?.kind ||
    !/(?:frustrat|angry|disappoint|失望|憤怒|愤怒)/i.test(
      plan.emotion_trace.kind,
    )
  ) return reply;
  const prefix = plan.language === "en"
    ? "I understand that this situation is frustrating. "
    : plan.language === "zh-CN"
    ? "我明白这个情况令人失望。 "
    : "我明白這個情況令人失望。 ";
  return reply.startsWith(prefix.trim()) ? reply : `${prefix}${reply}`;
}

export function renderServiceRecovery(
  plan: ServiceDialoguePlan,
  state: "no_match" | "tool_failure" | "conflict",
  language: ServiceLanguage,
): string {
  const l = language === "en" ? 2 : language === "zh-CN" ? 1 : 0;
  if (state === "conflict") {
    return [
      "我找到針對同一項目及適用範圍、但內容相反的現行資料。請告訴我要以哪個型號、地區或日期核對；我不會自行選一項當答案。",
      "我找到针对同一项目及适用范围、但内容相反的当前资料。请告诉我要以哪个型号、地区或日期核对；我不会自行选择一项作为答案。",
      "I found opposing current evidence for the same item and scope. Please specify the model, region, or date to verify; I will not choose one without evidence.",
    ][l];
  }
  if (state === "tool_failure") {
    return [
      "查詢工具目前未能完成，所以我不能核實商家的最新資料；本次沒有進行資料寫入或真人交接。你可以稍後再試，或選擇由真人客服接手。",
      "查询工具目前未能完成，所以我无法核实商家的最新资料；本次没有进行资料写入或人工交接。你可以稍后再试，或选择由人工客服接手。",
      "The lookup tool did not complete, so I cannot verify the merchant's latest information or claim that anything was saved or handed off. You can retry later or choose human support; no handoff has been performed yet.",
    ][l];
  }
  if (
    plan.action === "bounded_kb_refinement" ||
    plan.clarification_previously_asked
  ) {
    return [
      "這次知識庫查詢沒有返回可核實的現行資料。我不會重複問同一問題；你可以提供產品頁／更精確型號，或選擇由真人客服接手，目前尚未執行轉交。",
      "这次知识库查询没有返回可核实的当前资料。我不会重复问同一问题；你可以提供产品页／更精确型号，或选择由人工客服接手，目前尚未执行转交。",
      "This knowledge-base lookup returned no verifiable current answer. I will not repeat the same question; you can share a product page or exact model, or choose human support. No handoff has been performed yet.",
    ][l];
  }
  const question = renderTargetedServiceQuestion(plan, language);
  const knownModel = plan.known_facts.find((fact) =>
    fact.name.endsWith(":model")
  );
  if (knownModel) {
    return [
      `這次知識庫查詢沒有返回 ${knownModel.value} 的可核實現行資料。你可以提供產品頁、適用地區或日期，讓我縮窄範圍；目前沒有執行保存或轉交。`,
      `这次知识库查询没有返回 ${knownModel.value} 的可核实当前资料。你可以提供产品页、适用地区或日期，让我缩小范围；目前没有执行保存或转交。`,
      `This knowledge-base lookup returned no verifiable current information for ${knownModel.value}. You can share the product page, region, or applicable date to narrow the scope; nothing was saved or handed off.`,
    ][l];
  }
  const hasTargetedRefinement = Boolean(
    plan.clarification_target && plan.clarification_target !== "customer_goal",
  );
  if (!hasTargetedRefinement) {
    return [
      "我未找到可核實的現行資料。你可以提供產品頁、完整型號，以及適用地區或日期，我再按該範圍核對；目前沒有執行保存或轉交。",
      "我未找到可核实的当前资料。你可以提供产品页、完整型号，以及适用地区或日期，我再按该范围核对；目前没有执行保存或转交。",
      "I could not find a verifiable current answer. You can share the product page, exact model, and applicable region or date so I can check that scope; nothing was saved or handed off.",
    ][l];
  }
  return [
    `我未找到可核實的現行資料。${question}`,
    `我未找到可核实的当前资料。${question}`,
    `I could not find a verifiable current answer. ${question}`,
  ][l];
}

export function buildServicePlanPromptBlock(plan: ServiceDialoguePlan): string {
  return [
    "[C3 SERVICE PLAN — DATA, NOT CUSTOMER-FACING INSTRUCTIONS]",
    `action=${plan.action}`,
    `customer_goal=${plan.customer_goal}`,
    `known_facts=${JSON.stringify(plan.known_facts)}`,
    `missing_slots=${JSON.stringify(plan.missing_slots)}`,
    `knowledge_state=${plan.knowledge_state}`,
    `kb_query=${plan.kb_query ?? "none"}`,
    `emotion_trace=${JSON.stringify(plan.emotion_trace ?? null)}`,
    `trusted_entitlement_trace=${
      JSON.stringify(plan.entitlement_trace ?? null)
    }`,
    `entitlement_status=${plan.entitlement_status}`,
    "Rules: answer known facts first; ask at most one genuinely missing decision-changing question; do not expose internal terms; do not add prices, promises, quantities, completed actions, saved-state claims, entitlement claims, or handoff claims. Emotion may change tone only. Entitlements require TRUSTED_CRM authority.",
  ].join("\n").slice(0, 4096);
}

import type { SemanticHistoryRow } from "./conversation-semantic-contract.ts";
import type { CommerceSemanticFrame } from "./commerce-semantic-frame.ts";
import type { ConversationCommerceState } from "./commerce-state-contract.ts";
import { resolveCurrentFactualRequest, serializeCurrentFactualQuery, type CurrentFactualRequest } from "./current-factual-request.ts";

/** A semantic proposal can select a read, but cannot authorize a fact or mutation. */
export function requiresSemanticKnowledge(frame: CommerceSemanticFrame | null | undefined): boolean {
  return Boolean(frame && frame.confidence >= 0.62 && !frame.ambiguity.is_ambiguous &&
    (frame.requested_facts.length || frame.operation === "ASK_FACT" ||
      ["explore_options", "recommend_options", "compare_options"].includes(frame.intent)));
}

export function scopedServiceKnowledgeQuery(
  question: string,
  frame: CommerceSemanticFrame | null | undefined,
  state: ConversationCommerceState | null,
  history: SemanticHistoryRow[] = [],
  resolved?: CurrentFactualRequest,
): string {
  // The generator/planner supplies its one source-bound decision. Legacy
  // callers resolve once here; neither path reclassifies a provided contract.
  const input = {question, semantic: frame, commerce: state, history};
  const request = resolved ?? resolveCurrentFactualRequest(input);
  if (request.applicable && request.query !== null) return request.query;
  // Preserve the established typed-context serializer for callers that use
  // this utility to inspect requirements rather than dispatch a factual read.
  const trusted = frame && frame.confidence >= 0.62 && !frame.ambiguity.is_ambiguous ? frame : null;
  return serializeCurrentFactualQuery(input, {
    ...request,
    requested_facts: trusted?.requested_facts ?? [],
  }, true);
}

import { deriveTypedCustomerMoneyFacts } from "./customer-money-facts.ts";
import type { ConversationCommerceState } from "./commerce-state-contract.ts";
import type {
  ServiceCalculationTerm,
  ServicePlanInput,
} from "./conversation-service-planner.ts";

export const C3_SERVICE_RUNTIME_VERSION = "c3-service-runtime-1.0.0" as const;

export interface ServiceRuntimeMessage {
  role: string;
  content: string;
  id?: string | null;
}

export interface TypedCustomerCalculationTerm extends ServiceCalculationTerm {
  source: "customer_message";
  source_message_id?: string;
}
export interface TypedCustomerCalculation {
  terms: TypedCustomerCalculationTerm[];
  quantity?: number;
  status: "not_requested" | "ready" | "missing_explicit_basis" | "missing_quantity" | "mixed_currency" | "no_typed_amounts";
  calculation_type?: "historical_or_conditional";
  authority?: "customer_supplied_historical_or_hypothetical";
  current_price_authority?: "NONE";
  transaction_mutation?: "NONE";
  arithmetic_operation?: "multiply_then_add" | "addition";
  currency?: string;
  result?: number;
}

const CALCULATION_REQUEST = /(?:試算|试算|假設|假设|計算|计算|加埋|合共|總共|总共|一共|總數|总数|計下|计下|算下|計幾錢|计多少钱|算幾錢|算多少钱|calculate|estimate|total|altogether|how much|what\s+would.{0,80}\bcost\b)/i;
const HISTORICAL_OR_CONDITIONAL = /(?:舊|旧|之前|以前|頭先|刚才|剛才|用返|歷史|历史|假設|假设|如果|若果|若按|按你提供|historical|previous|earlier|conditional|hypothetical|\bif\b|\bassuming\b)/i;

function calcClean(value: unknown, limit = 2400): string {
  return String(value ?? "").normalize("NFKC").replace(/\s+/g, " ").trim().slice(0, limit);
}
function quantityValue(raw: string): number | null {
  const map: Record<string, number> = { "一": 1, "二": 2, "兩": 2, "两": 2, "三": 3, "四": 4, "五": 5, "六": 6, "七": 7, "八": 8, "九": 9, "十": 10, one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10 };
  if (/^\d{1,4}$/.test(raw)) return Number(raw);
  return map[raw.toLowerCase()] ?? null;
}
export function isReadOnlyCustomerCalculationRequest(text: string): boolean {
  const value = calcClean(text);
  // Use the same typed money parser as calculation/planning/Memory so local
  // currency wording cannot fall through to quantity recall.
  const hasMoney = deriveTypedCustomerMoneyFacts(value).facts.length > 0;
  return CALCULATION_REQUEST.test(value) && hasMoney && HISTORICAL_OR_CONDITIONAL.test(value) &&
    !/(?:落單|下單|下单|付款|支付|購買|购买|訂購|订购|正式報價|正式报价|place an order|checkout|pay now|purchase now|book now)/i.test(value);
}
export function isHistoricalOrConditionalCustomerCalculationRequest(text: string): boolean {
  return isReadOnlyCustomerCalculationRequest(text);
}
export function deriveTypedCustomerCalculation(input: {
  question: string; current_source_message_id?: string; recent_messages?: ServiceRuntimeMessage[];
  fallback_quantity?: number; fallback_quantity_source_message_id?: string;
}): TypedCustomerCalculation {
  const question = calcClean(input.question);
  if (!isReadOnlyCustomerCalculationRequest(question)) return { terms: [], status: "not_requested" };
  const money = deriveTypedCustomerMoneyFacts(question);
  const roleReference = /(?:用返|頭先|之前|earlier|previous|use).{0,24}(?:送貨費|送货费|delivery fee|installation fee|安裝費|安装费)/i.exec(question)?.[0];
  const recalled: TypedCustomerCalculationTerm[] = [];
  if (roleReference) {
    const role = /送貨|送货|delivery/i.test(roleReference) ? "delivery" : "installation";
    for (const row of input.recent_messages ?? []) {
      if (!/^(?:visitor|customer|user)$/.test(row.role) || row.id === input.current_source_message_id || row.content === input.question) continue;
      const prior = deriveTypedCustomerMoneyFacts(row.content);
      if (!prior.historical) continue;
      const matching = prior.facts.filter(f=>f.role===role);
      if (!matching.length) continue;
      if (matching.length !== 1 || !row.id) return {terms:[],status:"missing_explicit_basis"};
      const fact = matching[0];
      const basis = fact.charge_basis === "unspecified" && /加|plus|add/i.test(question)
        ? "per_order" : fact.charge_basis === "total" ? "per_order" : fact.charge_basis;
      if (basis === "unspecified") return {terms:[],status:"missing_explicit_basis"};
      recalled.push({label:fact.labels[2],amount:fact.amount,currency:fact.currency,charge_basis:basis,source:"customer_message",source_message_id:row.id});
      break;
    }
    if (!recalled.length) return {terms:[],status:"no_typed_amounts"};
  }
  if (money.facts.some((fact) => fact.charge_basis === "unspecified")) {
    return { terms: [], status: "missing_explicit_basis" };
  }
  const terms: TypedCustomerCalculationTerm[] = [...money.facts.map((fact) => ({
    label: fact.labels[2], amount: fact.amount, currency: fact.currency,
    charge_basis: (fact.charge_basis === "total" ? "per_order" : fact.charge_basis) as "per_unit" | "per_order",
    source: "customer_message" as const,
    ...(input.current_source_message_id ? { source_message_id: input.current_source_message_id } : {}),
  })),...recalled];
  if (!terms.length) return { terms: [], status: "no_typed_amounts" };
  if (new Set(terms.map((term) => term.currency)).size > 1) return { terms: [], status: "mixed_currency" };
  const qtyMatch = question.match(/(?:共|總共|总共|數量|数量|qty|quantity)?\s*(一|二|兩|两|三|四|五|六|七|八|九|十|one|two|three|four|five|six|seven|eight|nine|ten|\d{1,4})\s*(?:部|台|件|個|个|份|位|晚|夜|日|天|次|unit|units|item|items|session|sessions|night|nights|seat|seats)/i);
  const explicit = qtyMatch ? quantityValue(qtyMatch[1]) : null;
  const fallback = Number.isInteger(input.fallback_quantity) && Number(input.fallback_quantity) > 0 ? Number(input.fallback_quantity) : null;
  const quantity = explicit ?? fallback ?? undefined;
  if (terms.some((term) => term.charge_basis === "per_unit") && !quantity) return { terms: [], status: "missing_quantity" };
  return { terms, ...(quantity ? { quantity } : {}), status: "ready",
    calculation_type: "historical_or_conditional", authority: "customer_supplied_historical_or_hypothetical",
    current_price_authority: "NONE", transaction_mutation: "NONE",
    arithmetic_operation: terms.some((term) => term.charge_basis === "per_unit") ? "multiply_then_add" : "addition",
    currency: terms[0].currency,
    result: Math.round(terms.reduce((sum, term) => sum + term.amount * (term.charge_basis === "per_unit" ? quantity ?? 1 : 1), 0) * 100) / 100 };
}

export interface TrustedServiceEntitlement {
  name: string;
  value: string;
  authority: "TRUSTED_CRM";
  source: string;
}

export interface ServerCustomerContext {
  source: "customer360-adapter";
  conversation_id: string;
  company_id: string;
  customer_ref: string;
  request_id: string;
  source_identity: string;
  degraded: false;
  entitlements?: Array<{
    name: string;
    value: string;
    scope: string;
    valid_from?: string | null;
    valid_until?: string | null;
    status: "active" | "inactive";
  }>;
}

export interface ServiceRuntimeDerivation {
  version: typeof C3_SERVICE_RUNTIME_VERSION;
  calculation_terms: ServiceCalculationTerm[];
  calculation_quantity?: number;
  calculation_status:
    | "not_requested"
    | "ready"
    | "missing_explicit_basis"
    | "missing_quantity"
    | "mixed_currency"
    | "no_typed_amounts";
  calculation_type?: "historical_or_conditional";
  authority?: "customer_supplied_historical_or_hypothetical";
  current_price_authority?: "NONE";
  transaction_mutation?: "NONE";
  arithmetic_operation?: "multiply_then_add" | "addition";
  calculation_currency?: string;
  calculation_result?: number;
  entitlement: TrustedServiceEntitlement | null;
  entitlement_status: "trusted" | "unknown";
}

const clean = (value: unknown, limit = 1000) =>
  String(value ?? "").normalize("NFKC").replace(/\s+/g, " ").trim().slice(
    0,
    limit,
  );

export function resolveTrustedServiceEntitlement(input: {
  context: ServerCustomerContext | null;
  expected_conversation_id: string;
  expected_company_id: string;
  requested_scope: string;
  now?: Date;
}): TrustedServiceEntitlement | null {
  const context = input.context;
  if (
    !context || context.source !== "customer360-adapter" ||
    context.degraded !== false ||
    context.conversation_id !== input.expected_conversation_id ||
    context.company_id !== input.expected_company_id ||
    !clean(context.customer_ref) || !clean(context.request_id) ||
    !clean(context.source_identity)
  ) return null;
  const now = (input.now ?? new Date()).getTime();
  const candidates = (context.entitlements ?? []).filter((row) => {
    if (
      row.status !== "active" ||
      clean(row.scope) !== clean(input.requested_scope)
    ) return false;
    const from = row.valid_from
      ? Date.parse(row.valid_from)
      : Number.NEGATIVE_INFINITY;
    const until = row.valid_until
      ? Date.parse(row.valid_until)
      : Number.POSITIVE_INFINITY;
    return Number.isFinite(from) || from === Number.NEGATIVE_INFINITY
      ? (Number.isFinite(until) || until === Number.POSITIVE_INFINITY) &&
        from <= now && now <= until
      : false;
  });
  if (candidates.length !== 1) return null;
  const row = candidates[0];
  if (!clean(row.name) || !clean(row.value)) return null;
  return {
    name: clean(row.name, 80),
    value: clean(row.value, 120),
    authority: "TRUSTED_CRM",
    source: `customer360-adapter:${clean(context.source_identity, 80)}:${
      clean(context.request_id, 80)
    }:${clean(context.customer_ref, 128)}`,
  };
}

export function deriveServiceRuntimeInputs(input: {
  question: string;
  current_source_message_id?: string;
  recent_messages?: ServiceRuntimeMessage[];
  commerce: ConversationCommerceState | null;
  trusted_customer_context?: ServerCustomerContext | null;
  expected_conversation_id: string;
  expected_company_id: string;
  entitlement_scope?: string;
}): ServiceRuntimeDerivation {
  const typed = deriveTypedCustomerCalculation({
    question: input.question,
    current_source_message_id: input.current_source_message_id,
    recent_messages: input.recent_messages,
    fallback_quantity: (() => {
      const active = (input.commerce?.entities ?? []).filter((entity) =>
        !["cancelled", "deferred"].includes(entity.status)
      );
      return active.length === 1 ? active[0].quantity : undefined;
    })(),
    fallback_quantity_source_message_id: input.commerce?.entities.length === 1
      ? input.commerce.entities[0].provenance.source_message_id ?? undefined
      : undefined,
  });
  const calculation = {
    calculation_terms: typed.terms,
    calculation_quantity: typed.quantity,
    calculation_status: typed.status,
    calculation_type: typed.calculation_type,
    authority: typed.authority,
    current_price_authority: typed.current_price_authority,
    transaction_mutation: typed.transaction_mutation,
    arithmetic_operation: typed.arithmetic_operation,
    calculation_currency: typed.currency,
    calculation_result: typed.result,
  };
  const entitlement = resolveTrustedServiceEntitlement({
    context: input.trusted_customer_context ?? null,
    expected_conversation_id: input.expected_conversation_id,
    expected_company_id: input.expected_company_id,
    requested_scope: input.entitlement_scope ?? "customer_support",
  });
  return {
    version: C3_SERVICE_RUNTIME_VERSION,
    ...calculation,
    entitlement,
    entitlement_status: entitlement ? "trusted" : "unknown",
  };
}

export function applyServiceRuntimeDerivation(
  base: ServicePlanInput,
  derived: ServiceRuntimeDerivation,
): ServicePlanInput {
  return {
    ...base,
    calculation_terms: derived.calculation_terms,
    calculation_quantity: derived.calculation_quantity,
    calculation_status: derived.calculation_status,
    entitlement: derived.entitlement,
  };
}

import type { ServerCustomerContext } from "./conversation-service-runtime.ts";
import { resolveServerSecret } from "./nonproduction-secret.ts";
import { validateTrustedCustomerContext } from "./customer360-entitlement-contract.ts";
export { validateTrustedCustomerContext } from "./customer360-entitlement-contract.ts";

export async function fetchTrustedCustomerContext(input: {
  conversation_id: string;
  company_id: string;
  timeout_ms?: number;
}): Promise<ServerCustomerContext | null> {
  const url = Deno.env.get("SUPABASE_URL")?.replace(/\/+$/, "");
  const token = await resolveServerSecret(
    "CUSTOMER360_INTERNAL_TOKEN",
    "c3_customer360_internal_token",
  );
  if (!url || !token) return null;
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), input.timeout_ms ?? 5000);
  try {
    const response = await fetch(`${url}/functions/v1/customer360-adapter`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "X-Internal-Service-Token": token,
      },
      body: JSON.stringify({ conversation_id: input.conversation_id }),
      signal: controller.signal,
    });
    if (!response.ok) return null;
    return validateTrustedCustomerContext(await response.json(), input);
  } catch {
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

import type { ServerCustomerContext } from "./conversation-service-runtime.ts";

type Obj = Record<string, unknown>;
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const CUSTOMER = /^cus_[A-Za-z0-9_-]{16,64}$/;

const object = (value: unknown): Obj | null =>
  value && typeof value === "object" && !Array.isArray(value)
    ? value as Obj
    : null;
const text = (value: unknown, max: number): string | null =>
  typeof value === "string" && value.trim()
    ? value.normalize("NFKC").trim().slice(0, max)
    : null;

export function validateTrustedCustomerContext(
  payload: unknown,
  expected: { conversation_id: string; company_id: string },
): ServerCustomerContext | null {
  const root = object(payload);
  const raw = object(root?.trusted_customer_context);
  if (!root || root.success !== true || !raw) return null;
  const conversationId = text(raw.conversation_id, 36);
  const companyId = text(raw.company_id, 36);
  const customerRef = text(raw.customer_ref, 128);
  const requestId = text(raw.request_id, 128);
  const sourceIdentity = text(raw.source_identity, 160);
  if (
    raw.source !== "customer360-adapter" || raw.degraded !== false ||
    !conversationId || !companyId || !customerRef || !requestId ||
    !sourceIdentity || !UUID.test(conversationId) || !UUID.test(companyId) ||
    !CUSTOMER.test(customerRef) ||
    conversationId !== expected.conversation_id || companyId !== expected.company_id
  ) return null;
  if (!Array.isArray(raw.entitlements)) return null;
  const entitlements: ServerCustomerContext["entitlements"] = [];
  for (const item of raw.entitlements) {
    const row = object(item);
    const name = text(row?.name, 80);
    const value = text(row?.value, 120);
    const scope = text(row?.scope, 120);
    const status = row?.status;
    const validFrom = text(row?.valid_from, 80);
    const validUntil = text(row?.valid_until, 80);
    if (
      !row || !name || !value || !scope ||
      (status !== "active" && status !== "inactive") ||
      !validFrom || !validUntil || !Number.isFinite(Date.parse(validFrom)) ||
      !Number.isFinite(Date.parse(validUntil))
    ) return null;
    entitlements.push({
      name,
      value,
      scope,
      status,
      valid_from: validFrom,
      valid_until: validUntil,
    });
  }
  return {
    source: "customer360-adapter",
    conversation_id: conversationId,
    company_id: companyId,
    customer_ref: customerRef,
    request_id: requestId,
    source_identity: sourceIdentity,
    degraded: false,
    entitlements,
  };
}

